20260531120000	{"-- Fresh-start schema expansion for the Supabase-only ERP.\r\n-- Keeps the existing table names but adds the columns and tables needed by the new auth and role model.\r\n\r\ncreate extension if not exists pgcrypto","alter table if exists profiles\r\n  add column if not exists uid text,\r\n  add column if not exists roles text[] not null default '{}'::text[],\r\n  add column if not exists status text not null default 'ACTIVE',\r\n  add column if not exists customer_type text not null default 'CASH',\r\n  add column if not exists credit_limit numeric not null default 0,\r\n  add column if not exists used_credit numeric not null default 0,\r\n  add column if not exists business_name text,\r\n  add column if not exists photo_url text,\r\n  add column if not exists display_name text,\r\n  add column if not exists last_login timestamptz","update profiles\r\nset uid = coalesce(uid, id)\r\nwhere uid is null","do $$\r\nbegin\r\n  if not exists (\r\n    select 1 from pg_trigger where tgname = 'profiles_sync_uid_trigger'\r\n  ) then\r\n    create or replace function public.sync_profile_uid()\r\n    returns trigger\r\n    language plpgsql\r\n    as $fn$\r\n    begin\r\n      new.uid := coalesce(new.uid, new.id);\r\n      new.updated_at := coalesce(new.updated_at, now());\r\n      return new;\r\n    end;\r\n    $fn$;\r\n\r\n    create trigger profiles_sync_uid_trigger\r\n    before insert or update on profiles\r\n    for each row execute function public.sync_profile_uid();\r\n  end if;\r\nend $$","create table if not exists customers (\r\n  id text primary key,\r\n  profile_id text references profiles(id) on delete cascade,\r\n  name text not null,\r\n  email text,\r\n  phone text,\r\n  address text,\r\n  customer_type text not null default 'CASH',\r\n  credit_limit numeric not null default 0,\r\n  used_credit numeric not null default 0,\r\n  membership jsonb,\r\n  metadata jsonb not null default '{}'::jsonb,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n)","create table if not exists workflow (\r\n  id text primary key,\r\n  order_id text references orders(id) on delete cascade,\r\n  current_stage text,\r\n  workflow_role text,\r\n  status text,\r\n  payload jsonb,\r\n  metadata jsonb not null default '{}'::jsonb,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n)","create table if not exists accounts_ledger (\r\n  id text primary key,\r\n  customer_id text references profiles(id) on delete set null,\r\n  order_id text references orders(id) on delete set null,\r\n  entry_type text,\r\n  debit numeric not null default 0,\r\n  credit numeric not null default 0,\r\n  balance numeric not null default 0,\r\n  description text,\r\n  metadata jsonb not null default '{}'::jsonb,\r\n  created_at timestamptz not null default now()\r\n)","create table if not exists notifications (\r\n  id text primary key,\r\n  user_id text references profiles(id) on delete cascade,\r\n  title text not null,\r\n  body text,\r\n  status text not null default 'UNREAD',\r\n  metadata jsonb not null default '{}'::jsonb,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n)","create table if not exists reports (\r\n  id text primary key,\r\n  report_type text,\r\n  title text,\r\n  status text,\r\n  payload jsonb,\r\n  metadata jsonb not null default '{}'::jsonb,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n)","create table if not exists tally_sync_queue (\r\n  id text primary key,\r\n  order_id text references orders(id) on delete cascade,\r\n  status text not null default 'PENDING',\r\n  payload jsonb,\r\n  idempotency_key text,\r\n  error text,\r\n  metadata jsonb not null default '{}'::jsonb,\r\n  created_at timestamptz not null default now(),\r\n  updated_at timestamptz not null default now()\r\n)","create table if not exists audit_logs (\r\n  id text primary key,\r\n  action_type text not null,\r\n  actor_id text references profiles(id) on delete set null,\r\n  actor_name text,\r\n  target_id text,\r\n  target_type text,\r\n  payload jsonb,\r\n  metadata jsonb not null default '{}'::jsonb,\r\n  timestamp timestamptz not null default now()\r\n)","create table if not exists staff_users (\r\n  id text primary key,\r\n  uid text,\r\n  name text,\r\n  email text,\r\n  roles text[] not null default '{}'::text[],\r\n  status text not null default 'ACTIVE',\r\n  assigned_by text,\r\n  assigned_at timestamptz,\r\n  updated_at timestamptz,\r\n  suspended_at timestamptz,\r\n  last_login_at timestamptz,\r\n  metadata jsonb not null default '{}'::jsonb\r\n)","create table if not exists role_history (\r\n  id text primary key,\r\n  user_id text references profiles(id) on delete cascade,\r\n  user_name text,\r\n  old_roles text[] not null default '{}'::text[],\r\n  new_roles text[] not null default '{}'::text[],\r\n  changed_by text,\r\n  changed_by_name text,\r\n  changed_at timestamptz not null default now(),\r\n  reason text,\r\n  action text,\r\n  metadata jsonb not null default '{}'::jsonb\r\n)","create index if not exists idx_profiles_uid on profiles(uid)","create index if not exists idx_profiles_role on profiles(role)","create index if not exists idx_profiles_roles on profiles using gin(roles)","create index if not exists idx_customers_profile_id on customers(profile_id)","create index if not exists idx_notifications_user_id on notifications(user_id)","create index if not exists idx_workflow_order_id on workflow(order_id)","create index if not exists idx_tally_sync_queue_order_id on tally_sync_queue(order_id)"}	clean_supabase_only_schema
20260601120000	{"-- Add item-level product metadata for Supabase order_items rows.\r\n-- This supports the Firestore compatibility shim mapping orders/{id}/items -> order_items.\r\n-- Use quoted camelCase identifiers because the app expects `productName` and may preserve exact key casing.\r\n\r\nalter table if exists order_items\r\n  add column if not exists \\"productName\\" text not null default '',\r\n  add column if not exists \\"description\\" text"}	add_order_item_product_fields
20260614130000	{"-- Design Workspace Architecture: isolated per-item design tracking\n-- Creates separate tables for revision history, proofs, and comments\n-- so they never bloat the order_items JSONB column.\n\ncreate extension if not exists pgcrypto","-- ─── design_revisions ────────────────────────────────────────────────────────\ncreate table if not exists design_revisions (\n  id text primary key default gen_random_uuid()::text,\n  order_id text not null,\n  item_id text not null,\n  version integer not null default 1,\n  url text not null,\n  cloudinary_public_id text,\n  cloudinary_folder text,\n  uploaded_by text not null,\n  uploaded_by_name text,\n  uploaded_at timestamptz not null default now(),\n  notes text,\n  revision_type text not null default 'INITIAL',  -- INITIAL | CORRECTION | FINAL\n  upload_stats jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now()\n)","create index if not exists idx_design_revisions_order_item\n  on design_revisions(order_id, item_id)","create index if not exists idx_design_revisions_version\n  on design_revisions(order_id, item_id, version)","-- ─── design_proofs ────────────────────────────────────────────────────────────\ncreate table if not exists design_proofs (\n  id text primary key default gen_random_uuid()::text,\n  order_id text not null,\n  item_id text not null,\n  version integer not null default 1,\n  revision_version integer not null default 1,\n  url text not null,\n  cloudinary_public_id text,\n  sent_at timestamptz not null default now(),\n  sent_by text not null,\n  sent_by_name text,\n  customer_response text default 'PENDING',   -- PENDING | APPROVED | REJECTED\n  response_at timestamptz,\n  rejection_reason text,\n  notes text,\n  created_at timestamptz not null default now()\n)","create index if not exists idx_design_proofs_order_item\n  on design_proofs(order_id, item_id)","create index if not exists idx_design_proofs_version\n  on design_proofs(order_id, item_id, version)","-- ─── design_comments ──────────────────────────────────────────────────────────\ncreate table if not exists design_comments (\n  id text primary key default gen_random_uuid()::text,\n  order_id text not null,\n  item_id text not null,\n  message text not null,\n  author_id text not null,\n  author_name text,\n  author_role text,\n  attachment_url text,\n  created_at timestamptz not null default now()\n)","create index if not exists idx_design_comments_order_item\n  on design_comments(order_id, item_id)","-- ─── order_items: add itemWorkspace metadata column ──────────────────────────\nalter table if exists order_items\n  add column if not exists \\"designType\\" text,\n  add column if not exists \\"itemWorkspace\\" jsonb not null default '{}'::jsonb","create index if not exists idx_order_items_design_type\n  on order_items(\\"designType\\")"}	design_workspace_tables
20260614150000	{"-- Add tiff_path (production file path) and printer assignment columns to order_items.\n-- These fields are set by the manager when they save the production network file path\n-- before marking Work Done and assigning to a printer.\n\nalter table if exists order_items\n  add column if not exists tiff_path text,\n  add column if not exists tiff_assigned_at timestamptz,\n  add column if not exists tiff_assigned_by text,\n  add column if not exists \\"assignedPrinterId\\" text,\n  add column if not exists \\"assignedPrinterName\\" text","create index if not exists idx_order_items_tiff_path\n  on order_items(tiff_path)\n  where tiff_path is not null","create index if not exists idx_order_items_assigned_printer\n  on order_items(\\"assignedPrinterId\\")\n  where \\"assignedPrinterId\\" is not null"}	add_tiff_path_to_order_items
20260616120000	{"-- Migration for ERP V2.0 Architecture\n-- Creates document_jobs for the Persistent Job Queue\n-- Drops legacy dispatch_receipts and sales_receipts\n\n-- 1. Create document_jobs table for Persistent Job Queue\ncreate table if not exists document_jobs (\n  job_id text primary key,\n  job_type text not null,\n  order_id text not null,\n  parent_order_id text not null,\n  priority integer not null default 2,\n  status text not null default 'PENDING',\n  attempts integer not null default 0,\n  max_attempts integer not null default 3,\n  last_error text,\n  worker_id text,\n  metadata jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  started_at timestamptz,\n  completed_at timestamptz\n)","-- Index for worker polling\ncreate index if not exists idx_document_jobs_status_priority on document_jobs (status, priority, created_at)","-- 2. Drop legacy tables\ndrop table if exists dispatch_receipts cascade","drop table if exists sales_receipts cascade","-- Note: The closures will now go into transactions (accounts_ledger or equivalent)."}	erp_v2_architecture
20260616130000	{"-- SQL Migration: place_order_tx PL/pgSQL Function\n-- Executes the entire parent/child order placement, ledger inserts, credit checks, and job queueing in a single ACID transaction.\n\nCREATE OR REPLACE FUNCTION place_order_tx(\n  p_customer_id text,\n  p_order_type text,\n  p_grand_total numeric,\n  p_parent_order jsonb,\n  p_child_orders jsonb[],\n  p_order_items jsonb[],\n  p_ledger_entries jsonb[],\n  p_jobs jsonb[]\n) RETURNS jsonb LANGUAGE plpgsql AS $$\nDECLARE\n  v_used_credit numeric;\n  v_credit_limit numeric;\n  v_new_used_credit numeric;\n  child_val jsonb;\n  item_val jsonb;\n  ledger_val jsonb;\n  job_val jsonb;\n  v_result jsonb;\nBEGIN\n  -- 1. Read and Lock Customer Profile Row\n  SELECT COALESCE(\\"usedCredit\\", 0), COALESCE(\\"creditLimit\\", 0)\n  INTO v_used_credit, v_credit_limit\n  FROM profiles\n  WHERE id = p_customer_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Customer profile not found for ID %', p_customer_id;\n  END IF;\n\n  -- 2. Validate Credit Limit (if CREDIT customer)\n  IF p_order_type = 'CREDIT' THEN\n    IF (v_used_credit + p_grand_total) > v_credit_limit THEN\n      RAISE EXCEPTION 'Credit limit exceeded. Current used: %, Limit: %, Requested: %', v_used_credit, v_credit_limit, p_grand_total;\n    END IF;\n  END IF;\n\n  -- 3. Update Locked Customer Used Credit Balance\n  v_new_used_credit := v_used_credit + p_grand_total;\n  UPDATE profiles\n  SET \\"usedCredit\\" = v_new_used_credit, \\"updatedAt\\" = NOW()\n  WHERE id = p_customer_id;\n\n  -- 4. Insert Parent Order (if provided)\n  -- If N=1, the parent order is the single order.\n  -- If N>1, the parent order is the grouping container.\n  IF p_parent_order IS NOT NULL THEN\n    INSERT INTO orders (\n      id, \\"customerId\\", \\"customerName\\", \\"customerSnapshot\\", \\"orderType\\", \\"orderSource\\",\n      \\"createdBy\\", \\"createdByRole\\", \\"proxyExecutor\\", \\"printerCategory\\", amounts, delivery,\n      workflow, \\"workflowSnapshot\\", \\"currentWorkflowRole\\", \\"currentWorkflowLabel\\",\n      \\"productionNotes\\", \\"thumbnailUrl\\", \\"productName\\", \\"description\\", items, status, \\"paymentStatus\\",\n      \\"createdAt\\", \\"updatedAt\\", \\"shippingAddress\\", \\"deliveryChoice\\"\n    ) VALUES (\n      p_parent_order->>'id',\n      p_parent_order->>'customerId',\n      p_parent_order->>'customerName',\n      COALESCE(p_parent_order->'customerSnapshot', '{}'::jsonb),\n      p_parent_order->>'orderType',\n      p_parent_order->>'orderSource',\n      p_parent_order->>'createdBy',\n      p_parent_order->>'createdByRole',\n      p_parent_order->'proxyExecutor',\n      p_parent_order->>'printerCategory',\n      p_parent_order->'amounts',\n      p_parent_order->'delivery',\n      p_parent_order->'workflow',\n      p_parent_order->'workflowSnapshot',\n      p_parent_order->>'currentWorkflowRole',\n      p_parent_order->>'currentWorkflowLabel',\n      p_parent_order->>'productionNotes',\n      p_parent_order->>'thumbnailUrl',\n      p_parent_order->>'productName',\n      p_parent_order->>'description',\n      COALESCE(p_parent_order->'items', '[]'::jsonb),\n      p_parent_order->>'status',\n      p_parent_order->>'paymentStatus',\n      COALESCE(p_parent_order->>'createdAt', NOW()::text),\n      COALESCE(p_parent_order->>'updatedAt', NOW()::text),\n      p_parent_order->>'shippingAddress',\n      p_parent_order->>'deliveryChoice'\n    );\n  END IF;\n\n  -- 5. Insert Child Orders (Batch)\n  IF p_child_orders IS NOT NULL THEN\n    FOREACH child_val IN ARRAY p_child_orders LOOP\n      INSERT INTO orders (\n        id, \\"customerId\\", \\"customerName\\", \\"customerSnapshot\\", \\"orderType\\", \\"orderSource\\",\n        \\"createdBy\\", \\"createdByRole\\", \\"proxyExecutor\\", \\"printerCategory\\", amounts, delivery,\n        workflow, \\"workflowSnapshot\\", \\"currentWorkflowRole\\", \\"currentWorkflowLabel\\",\n        \\"productionNotes\\", \\"thumbnailUrl\\", \\"productName\\", \\"description\\", items, status, \\"paymentStatus\\",\n        \\"createdAt\\", \\"updatedAt\\", \\"shippingAddress\\", \\"deliveryChoice\\"\n      ) VALUES (\n        child_val->>'id',\n        child_val->>'customerId',\n        child_val->>'customerName',\n        COALESCE(child_val->'customerSnapshot', '{}'::jsonb),\n        child_val->>'orderType',\n        child_val->>'orderSource',\n        child_val->>'createdBy',\n        child_val->>'createdByRole',\n        child_val->'proxyExecutor',\n        child_val->>'printerCategory',\n        child_val->'amounts',\n        child_val->'delivery',\n        child_val->'workflow',\n        child_val->'workflowSnapshot',\n        child_val->>'currentWorkflowRole',\n        child_val->>'currentWorkflowLabel',\n        child_val->>'productionNotes',\n        child_val->>'thumbnailUrl',\n        child_val->>'productName',\n        child_val->>'description',\n        COALESCE(child_val->'items', '[]'::jsonb),\n        child_val->>'status',\n        child_val->>'paymentStatus',\n        COALESCE(child_val->>'createdAt', NOW()::text),\n        COALESCE(child_val->>'updatedAt', NOW()::text),\n        child_val->>'shippingAddress',\n        child_val->>'deliveryChoice'\n      );\n    END LOOP;\n  END IF;\n\n  -- 6. Insert Order Items into order_items table (Batch)\n  IF p_order_items IS NOT NULL THEN\n    FOREACH item_val IN ARRAY p_order_items LOOP\n      INSERT INTO order_items (\n        id, order_id, product_name, product_id, category, project_name, specs, material_metadata,\n        pricing_snapshot, file_url, design_url, design_status, design_upload_stats,\n        \\"assignedPrinterId\\", \\"assignedPrinterName\\", \\"fileUrl\\", \\"productId\\", \\"productName\\",\n        \\"projectName\\", \\"materialMetadata\\", \\"pricingSnapshot\\", \\"designUrl\\", \\"designStatus\\",\n        \\"designUploadStats\\", description, \\"designType\\", \\"itemWorkspace\\", created_at, updated_at\n      ) VALUES (\n        item_val->>'id',\n        item_val->>'orderId',\n        item_val->>'productName',\n        item_val->>'productId',\n        item_val->>'category',\n        item_val->>'projectName',\n        COALESCE(item_val->'specs', '{}'::jsonb),\n        COALESCE(item_val->'materialMetadata', '{}'::jsonb),\n        COALESCE(item_val->'pricingSnapshot', '{}'::jsonb),\n        item_val->>'fileUrl',\n        item_val->>'designUrl',\n        item_val->>'designStatus',\n        COALESCE(item_val->'designUploadStats', '{}'::jsonb),\n        item_val->>'assignedPrinterId',\n        item_val->>'assignedPrinterName',\n        item_val->>'fileUrl',\n        item_val->>'productId',\n        item_val->>'productName',\n        item_val->>'projectName',\n        COALESCE(item_val->'materialMetadata', '{}'::jsonb),\n        COALESCE(item_val->'pricingSnapshot', '{}'::jsonb),\n        item_val->>'designUrl',\n        item_val->>'designStatus',\n        COALESCE(item_val->'designUploadStats', '{}'::jsonb),\n        item_val->>'description',\n        item_val->>'designType',\n        COALESCE(item_val->'itemWorkspace', '{}'::jsonb),\n        NOW(),\n        NOW()\n      );\n    END LOOP;\n  END IF;\n\n  -- 7. Insert Ledger Entries into transactions table (Batch)\n  IF p_ledger_entries IS NOT NULL THEN\n    FOREACH ledger_val IN ARRAY p_ledger_entries LOOP\n      INSERT INTO transactions (\n        id, \\"userId\\", type, \\"ledgerType\\", \\"refId\\", debit, credit, \\"balanceBefore\\", \\"balanceAfter\\",\n        \\"availableCredit\\", remarks, \\"createdBy\\", timestamp, \\"isVerified\\", \\"verifiedAt\\", \\"verifiedBy\\",\n        \\"paymentId\\"\n      ) VALUES (\n        ledger_val->>'id',\n        ledger_val->>'userId',\n        ledger_val->>'type',\n        ledger_val->>'ledgerType',\n        ledger_val->>'refId',\n        COALESCE((ledger_val->>'debit')::numeric, 0),\n        COALESCE((ledger_val->>'credit')::numeric, 0),\n        COALESCE((ledger_val->>'balanceBefore')::numeric, 0),\n        COALESCE((ledger_val->>'balanceAfter')::numeric, 0),\n        COALESCE((ledger_val->>'availableCredit')::numeric, 0),\n        ledger_val->>'remarks',\n        ledger_val->>'createdBy',\n        NOW(),\n        COALESCE((ledger_val->>'isVerified')::boolean, false),\n        CASE WHEN ledger_val->>'verifiedAt' IS NOT NULL THEN (ledger_val->>'verifiedAt')::timestamptz ELSE NULL END,\n        ledger_val->>'verifiedBy',\n        ledger_val->>'paymentId'\n      );\n    END LOOP;\n  END IF;\n\n  -- 8. Insert Background Jobs into document_jobs table (Batch)\n  IF p_jobs IS NOT NULL THEN\n    FOREACH job_val IN ARRAY p_jobs LOOP\n      INSERT INTO document_jobs (\n        job_id, job_type, order_id, parent_order_id, priority, status, created_at\n      ) VALUES (\n        job_val->>'jobId',\n        job_val->>'jobType',\n        job_val->>'orderId',\n        p_parent_order->>'id',\n        COALESCE((job_val->>'priority')::integer, 2),\n        'PENDING',\n        NOW()\n      );\n    END LOOP;\n  END IF;\n\n  v_result := jsonb_build_object(\n    'success', true,\n    'orderId', p_parent_order->>'id',\n    'balanceBefore', v_used_credit,\n    'balanceAfter', v_new_used_credit\n  );\n  \n  RETURN v_result;\nEND;\n$$"}	place_order_tx
