\", \\"productName\\", \\"description\\", items, status, \\"paymentStatus\\",\n      \\"createdAt\\", \\"updatedAt\\", \\"shippingAddress\\", \\"deliveryChoice\\"\n    ) VALUES (\n      p_parent_order->>'id',\n      p_parent_order->>'customerId',\n      p_parent_order->>'customerName',\n      COALESCE(p_parent_order->'customerSnapshot', '{}'::jsonb),\n      p_parent_order->>'orderType',\n      p_parent_order->>'orderSource',\n      p_parent_order->>'createdBy',\n      p_parent_order->>'createdByRole',\n      p_parent_order->'proxyExecutor',\n      p_parent_order->>'printerCategory',\n      p_parent_order->'amounts',\n      p_parent_order->'delivery',\n      p_parent_order->'workflow',\n      p_parent_order->'workflowSnapshot',\n      p_parent_order->>'currentWorkflowRole',\n      p_parent_order->>'currentWorkflowLabel',\n      p_parent_order->>'productionNotes',\n      p_parent_order->>'thumbnailUrl',\n      p_parent_order->>'productName',\n      p_parent_order->>'description',\n      COALESCE(p_parent_order->'items', '[]'::jsonb),\n      p_parent_order->>'status',\n      p_parent_order->>'paymentStatus',\n      COALESCE(p_parent_order->'createdAt', to_jsonb(NOW()::text)),\n      COALESCE(p_parent_order->'updatedAt', to_jsonb(NOW()::text)),\n      p_parent_order->>'shippingAddress',\n      p_parent_order->>'deliveryChoice'\n    );\n  END IF;\n\n  -- 5. Insert Child Orders (Batch)\n  IF p_child_orders IS NOT NULL THEN\n    FOREACH child_val IN ARRAY p_child_orders LOOP\n      INSERT INTO orders (\n        id, \\"customerId\\", \\"customerName\\", \\"customerSnapshot\\", \\"orderType\\", \\"orderSource\\",\n        \\"createdBy\\", \\"createdByRole\\", \\"proxyExecutor\\", \\"printerCategory\\", amounts, delivery,\n        workflow, \\"workflowSnapshot\\", \\"currentWorkflowRole\\", \\"currentWorkflowLabel\\",\n        \\"productionNotes\\", \\"thumbnailUrl\\", \\"productName\\", \\"description\\", items, status, \\"paymentStatus\\",\n        \\"createdAt\\", \\"updatedAt\\", \\"shippingAddress\\", \\"deliveryChoice\\"\n      ) VALUES (\n        child_val->>'id',\n        child_val->>'customerId',\n        child_val->>'customerName',\n        COALESCE(child_val->'customerSnapshot', '{}'::jsonb),\n        child_val->>'orderType',\n        child_val->>'orderSource',\n        child_val->>'createdBy',\n        child_val->>'createdByRole',\n        child_val->'proxyExecutor',\n        child_val->>'printerCategory',\n        child_val->'amounts',\n        child_val->'delivery',\n        child_val->'workflow',\n        child_val->'workflowSnapshot',\n        child_val->>'currentWorkflowRole',\n        child_val->>'currentWorkflowLabel',\n        child_val->>'productionNotes',\n        child_val->>'thumbnailUrl',\n        child_val->>'productName',\n        child_val->>'description',\n        COALESCE(child_val->'items', '[]'::jsonb),\n        child_val->>'status',\n        child_val->>'paymentStatus',\n        COALESCE(child_val->'createdAt', to_jsonb(NOW()::text)),\n        COALESCE(child_val->'updatedAt', to_jsonb(NOW()::text)),\n        child_val->>'shippingAddress',\n        child_val->>'deliveryChoice'\n      );\n    END LOOP;\n  END IF;\n\n  -- 6. Insert Order Items into order_items table (Batch)\n  IF p_order_items IS NOT NULL THEN\n    FOREACH item_val IN ARRAY p_order_items LOOP\n      INSERT INTO order_items (\n        id, order_id, product_name, product_id, category, project_name, specs, material_metadata,\n        pricing_snapshot, file_url, design_url, design_status, design_upload_stats,\n        \\"assignedPrinterId\\", \\"assignedPrinterName\\", \\"fileUrl\\", \\"productId\\", \\"productName\\",\n        \\"projectName\\", \\"materialMetadata\\", \\"pricingSnapshot\\", \\"designUrl\\", \\"designStatus\\",\n        \\"designUploadStats\\", description, \\"designType\\", \\"itemWorkspace\\", created_at, updated_at\n      ) VALUES (\n        item_val->>'id',\n        item_val->>'orderId',\n        item_val->>'productName',\n        item_val->>'productId',\n        item_val->>'category',\n        item_val->>'projectName',\n        COALESCE(item_val->'specs', '{}'::jsonb),\n        COALESCE(item_val->'materialMetadata', '{}'::jsonb),\n        COALESCE(item_val->'pricingSnapshot', '{}'::jsonb),\n        item_val->>'fileUrl',\n        item_val->>'designUrl',\n        item_val->>'designStatus',\n        COALESCE(item_val->'designUploadStats', '{}'::jsonb),\n        item_val->>'assignedPrinterId',\n        item_val->>'assignedPrinterName',\n        item_val->>'fileUrl',\n        item_val->>'productId',\n        item_val->>'productName',\n        item_val->>'projectName',\n        COALESCE(item_val->'materialMetadata', '{}'::jsonb),\n        COALESCE(item_val->'pricingSnapshot', '{}'::jsonb),\n        item_val->>'designUrl',\n        item_val->>'designStatus',\n        COALESCE(item_val->'designUploadStats', '{}'::jsonb),\n        item_val->>'description',\n        item_val->>'designType',\n        COALESCE(item_val->'itemWorkspace', '{}'::jsonb),\n        NOW(),\n        NOW()\n      );\n    END LOOP;\n  END IF;\n\n  -- 7. Insert Ledger Entries into transactions table (Batch)\n  IF p_ledger_entries IS NOT NULL THEN\n    FOREACH ledger_val IN ARRAY p_ledger_entries LOOP\n      INSERT INTO transactions (\n        id, \\"userId\\", type, \\"ledgerType\\", \\"refId\\", debit, credit, \\"balanceBefore\\", \\"balanceAfter\\",\n        \\"availableCredit\\", remarks, \\"createdBy\\", timestamp, \\"isVerified\\", \\"verifiedAt\\", \\"verifiedBy\\",\n        \\"paymentId\\"\n      ) VALUES (\n        ledger_val->>'id',\n        ledger_val->>'userId',\n        ledger_val->>'type',\n        ledger_val->>'ledgerType',\n        ledger_val->>'refId',\n        COALESCE((ledger_val->>'debit')::numeric, 0),\n        COALESCE((ledger_val->>'credit')::numeric, 0),\n        COALESCE((ledger_val->>'balanceBefore')::numeric, 0),\n        COALESCE((ledger_val->>'balanceAfter')::numeric, 0),\n        COALESCE((ledger_val->>'availableCredit')::numeric, 0),\n        ledger_val->>'remarks',\n        ledger_val->>'createdBy',\n        to_jsonb(NOW()::text),\n        COALESCE((ledger_val->>'isVerified')::boolean, false),\n        CASE WHEN ledger_val->>'verifiedAt' IS NOT NULL THEN to_jsonb(ledger_val->>'verifiedAt') ELSE NULL END,\n        ledger_val->>'verifiedBy',\n        ledger_val->>'paymentId'\n      );\n    END LOOP;\n  END IF;\n\n  -- 8. Insert Background Jobs into document_jobs table (Batch)\n  IF p_jobs IS NOT NULL THEN\n    FOREACH job_val IN ARRAY p_jobs LOOP\n      INSERT INTO document_jobs (\n        job_id, job_type, order_id, parent_order_id, priority, status, created_at\n      ) VALUES (\n        job_val->>'jobId',\n        job_val->>'jobType',\n        job_val->>'orderId',\n        p_parent_order->>'id',\n        COALESCE((job_val->>'priority')::integer, 2),\n        'PENDING',\n        NOW()\n      );\n    END LOOP;\n  END IF;\n\n  v_result := jsonb_build_object(\n    'success', true,\n    'orderId', p_parent_order->>'id',\n    'balanceBefore', v_used_credit,\n    'balanceAfter', v_new_used_credit\n  );\n  \n  RETURN v_result;\nEND;\n$$"}	fix_place_order_tx_ledger
20260616133000	{"-- SQL Migration: claim_pending_job function\n-- Claims a pending job atomically, locking the row and marking it RUNNING to prevent concurrency races.\n\nCREATE OR REPLACE FUNCTION claim_pending_job(\n  p_worker_id text,\n  p_now timestamptz\n) RETURNS SETOF document_jobs LANGUAGE plpgsql AS $$\nDECLARE\n  v_job_id text;\nBEGIN\n  -- 1. Select one pending job id atomically\n  SELECT job_id INTO v_job_id\n  FROM document_jobs\n  WHERE status = 'PENDING'\n    AND (\n      metadata->>'runAfter' IS NULL\n      OR (metadata->>'runAfter')::timestamptz <= p_now\n    )\n  ORDER BY priority ASC, created_at ASC\n  FOR UPDATE SKIP LOCKED\n  LIMIT 1;\n\n  -- 2. If a job is found, update it to RUNNING status\n  IF v_job_id IS NOT NULL THEN\n    RETURN QUERY\n    UPDATE document_jobs\n    SET status = 'RUNNING',\n        started_at = p_now,\n        worker_id = p_worker_id\n    WHERE job_id = v_job_id\n    RETURNING *;\n  END IF;\n\n  RETURN;\nEND;\n$$"}	claim_pending_job
20260616140000	{"-- SQL Migration: Migrate job queue to camelCase columns and add worker timeouts/debugging fields\n-- Enforces row-level safety, preserves data, and updates RPCs.\n\nDO $$\nBEGIN\n  -- Rename job_id to id\n  IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'document_jobs'::regclass AND attname = 'job_id') THEN\n    ALTER TABLE document_jobs RENAME COLUMN job_id TO id;\n  END IF;\n\n  -- Rename job_type to \\"jobType\\"\n  IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'document_jobs'::regclass AND attname = 'job_type') THEN\n    ALTER TABLE document_jobs RENAME COLUMN job_type TO \\"jobType\\";\n  END IF;\n\n  -- Rename order_id to \\"orderId\\"\n  IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'document_jobs'::regclass AND attname = 'order_id') THEN\n    ALTER TABLE document_jobs RENAME COLUMN order_id TO \\"orderId\\";\n  END IF;\n\n  -- Rename parent_order_id to \\"parentOrderId\\"\n  IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'document_jobs'::regclass AND attname = 'parent_order_id') THEN\n    ALTER TABLE document_jobs RENAME COLUMN parent_order_id TO \\"parentOrderId\\";\n  END IF;\n\n  -- Rename max_attempts to \\"maxAttempts\\"\n  IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'document_jobs'::regclass AND attname = 'max_attempts') THEN\n    ALTER TABLE document_jobs RENAME COLUMN max_attempts TO \\"maxAttempts\\";\n  END IF;\n\n  -- Rename last_error to \\"errorMessage\\"\n  IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'document_jobs'::regclass AND attname = 'last_error') THEN\n    ALTER TABLE document_jobs RENAME COLUMN last_error TO \\"errorMessage\\";\n  END IF;\n\n  -- Rename created_at to \\"createdAt\\"\n  IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'document_jobs'::regclass AND attname = 'created_at') THEN\n    ALTER TABLE document_jobs RENAME COLUMN created_at TO \\"createdAt\\";\n  END IF;\n\n  -- Rename started_at to \\"startedAt\\"\n  IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'document_jobs'::regclass AND attname = 'started_at') THEN\n    ALTER TABLE document_jobs RENAME COLUMN started_at TO \\"startedAt\\";\n  END IF;\n\n  -- Rename completed_at to \\"completedAt\\"\n  IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'document_jobs'::regclass AND attname = 'completed_at') THEN\n    ALTER TABLE document_jobs RENAME COLUMN completed_at TO \\"completedAt\\";\n  END IF;\n\n  -- Rename metadata to \\"payload\\"\n  IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'document_jobs'::regclass AND attname = 'metadata') THEN\n    ALTER TABLE document_jobs RENAME COLUMN metadata TO \\"payload\\";\n  END IF;\nEND $$","-- Add new fields if they don't exist\nALTER TABLE document_jobs ADD COLUMN IF NOT EXISTS \\"failedAt\\" timestamptz","ALTER TABLE document_jobs ADD COLUMN IF NOT EXISTS \\"heartbeatAt\\" timestamptz","ALTER TABLE document_jobs ADD COLUMN IF NOT EXISTS \\"stackTrace\\" text","ALTER TABLE document_jobs ADD COLUMN IF NOT EXISTS \\"sqlError\\" text","ALTER TABLE document_jobs ADD COLUMN IF NOT EXISTS \\"workerVersion\\" text","-- Ensure default values\nALTER TABLE document_jobs ALTER COLUMN \\"maxAttempts\\" SET DEFAULT 4","ALTER TABLE document_jobs ALTER COLUMN \\"payload\\" SET DEFAULT '{}'::jsonb","-- Recreate index on status, priority, and createdAt for claiming performance\nDROP INDEX IF EXISTS idx_document_jobs_status_priority","CREATE INDEX IF NOT EXISTS idx_document_jobs_status_priority ON document_jobs (status, priority, \\"createdAt\\")","-- Recreate claim_pending_job function with heartbeat timeout and camelCase columns\nCREATE OR REPLACE FUNCTION claim_pending_job(\n  p_worker_id text,\n  p_now timestamptz\n) RETURNS SETOF document_jobs LANGUAGE plpgsql AS $$\nDECLARE\n  v_job_id text;\nBEGIN\n  -- 1. Self-healing: Reset timed-out running jobs (no heartbeat/startedAt for > 5 minutes)\n  -- Timed-out jobs are rescheduled for retry by incrementing attempts\n  UPDATE document_jobs\n  SET status = CASE WHEN attempts + 1 >= \\"maxAttempts\\" THEN 'FAILED' ELSE 'RETRYING' END,\n      attempts = attempts + 1,\n      \\"failedAt\\" = CASE WHEN attempts + 1 >= \\"maxAttempts\\" THEN p_now ELSE NULL END,\n      \\"errorMessage\\" = 'Worker timeout (No heartbeat/startedAt updated for 5 minutes)'\n  WHERE status = 'RUNNING'\n    AND COALESCE(\\"heartbeatAt\\", \\"startedAt\\") <= p_now - INTERVAL '5 minutes';\n\n  -- 2. Select one pending or retrying job atomically\n  SELECT id INTO v_job_id\n  FROM document_jobs\n  WHERE status IN ('PENDING', 'RETRYING')\n    AND (\n      \\"payload\\"->>'runAfter' IS NULL\n      OR (\\"payload\\"->>'runAfter')::timestamptz <= p_now\n    )\n  ORDER BY priority ASC, \\"createdAt\\" ASC\n  FOR UPDATE SKIP LOCKED\n  LIMIT 1;\n\n  -- 3. If a job is found, update it to RUNNING status\n  IF v_job_id IS NOT NULL THEN\n    RETURN QUERY\n    UPDATE document_jobs\n    SET status = 'RUNNING',\n        \\"startedAt\\" = p_now,\n        \\"heartbeatAt\\" = p_now,\n        worker_id = p_worker_id\n    WHERE id = v_job_id\n    RETURNING *;\n  END IF;\n\n  RETURN;\nEND;\n$$","-- Recreate place_order_tx to support camelCase job insert\nCREATE OR REPLACE FUNCTION place_order_tx(\n  p_customer_id text,\n  p_order_type text,\n  p_grand_total numeric,\n  p_parent_order jsonb,\n  p_child_orders jsonb[],\n  p_order_items jsonb[],\n  p_ledger_entries jsonb[],\n  p_jobs jsonb[]\n) RETURNS jsonb LANGUAGE plpgsql AS $$\nDECLARE\n  v_used_credit numeric;\n  v_credit_limit numeric;\n  v_new_used_credit numeric;\n  child_val jsonb;\n  item_val jsonb;\n  ledger_val jsonb;\n  job_val jsonb;\n  v_result jsonb;\nBEGIN\n  -- 1. Read and Lock Customer Profile Row\n  SELECT COALESCE(\\"usedCredit\\", 0), COALESCE(\\"creditLimit\\", 0)\n  INTO v_used_credit, v_credit_limit\n  FROM profiles\n  WHERE id = p_customer_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Customer profile not found for ID %', p_customer_id;\n  END IF;\n\n  -- 2. Validate Credit Limit (if CREDIT customer)\n  IF p_order_type = 'CREDIT' THEN\n    IF (v_used_credit + p_grand_total) > v_credit_limit THEN\n      RAISE EXCEPTION 'Credit limit exceeded. Current used: %, Limit: %, Requested: %', v_used_credit, v_credit_limit, p_grand_total;\n    END IF;\n  END IF;\n\n  -- 3. Update Locked Customer Used Credit Balance\n  v_new_used_credit := v_used_credit + p_grand_total;\n  UPDATE profiles\n  SET \\"usedCredit\\" = v_new_used_credit, \\"updatedAt\\" = to_jsonb(NOW()::text)\n  WHERE id = p_customer_id;\n\n  -- 4. Insert Parent Order (if provided)\n  IF p_parent_order IS NOT NULL THEN\n    INSERT INTO orders (\n      id, \\"customerId\\", \\"customerName\\", \\"customerSnapshot\\", \\"orderType\\", \\"orderSource\\",\n      \\"createdBy\\", \\"createdByRole\\", \\"proxyExecutor\\", \\"printerCategory\\", amounts, delivery,\n      workflow, \\"workflowSnapshot\\", \\"currentWorkflowRole\\", \\"currentWorkflowLabel\\",\n      \\"productionNotes\\", \\"thumbnailUrl\\", \\"productName\\", \\"description\\", items, status, \\"paymentStatus\\",\n      \\"createdAt\\", \\"updatedAt\\", \\"shippingAddress\\", \\"deliveryChoice\\"\n    ) VALUES (\n      p_parent_order->>'id',\n      p_parent_order->>'customerId',\n      p_parent_order->>'customerName',\n      COALESCE(p_parent_order->'customerSnapshot', '{}'::jsonb),\n      p_parent_order->>'orderType',\n      p_parent_order->>'orderSource',\n      p_parent_order->>'createdBy',\n      p_parent_order->>'createdByRole',\n      p_parent_order->'proxyExecutor',\n      p_parent_order->>'printerCategory',\n      p_parent_order->'amounts',\n      p_parent_order->'delivery',\n      p_parent_order->'workflow',\n      p_parent_order->'workflowSnapshot',\n      p_parent_order->>'currentWorkflowRole',\n      p_parent_order->>'currentWorkflowLabel',\n      p_parent_order->>'productionNotes',\n      p_parent_order->>'thumbnailUrl',\n      p_parent_order->>'productName',\n      p_parent_order->>'description',\n      COALESCE(p_parent_order->'items', '[]'::jsonb),\n      p_parent_order->>'status',\n      p_parent_order->>'paymentStatus',\n      COALESCE(p_parent_order->'createdAt', to_jsonb(NOW()::text)),\n      COALESCE(p_parent_order->'updatedAt', to_jsonb(NOW()::text)),\n      p_parent_order->>'shippingAddress',\n      p_parent_order->>'deliveryChoice'\n    );\n  END IF;\n\n  -- 5. Insert Child Orders (Batch)\n  IF p_child_orders IS NOT NULL THEN\n    FOREACH child_val IN ARRAY p_child_orders LOOP\n      INSERT INTO orders (\n        id, \\"customerId\\", \\"customerName\\", \\"customerSnapshot\\", \\"orderType\\", \\"orderSource\\",\n        \\"createdBy\\", \\"createdByRole\\", \\"proxyExecutor\\", \\"printerCategory\\", amounts, delivery,\n        workflow, \\"workflowSnapshot\\", \\"currentWorkflowRole\\", \\"currentWorkflowLabel\\",\n        \\"productionNotes\\", \\"thumbnailUrl\\", \\"productName\\", \\"description\\", items, status, \\"paymentStatus\\",\n        \\"createdAt\\", \\"updatedAt\\", \\"shippingAddress\\", \\"deliveryChoice\\"\n      ) VALUES (\n        child_val->>'id',\n        child_val->>'customerId',\n        child_val->>'customerName',\n        COALESCE(child_val->'customerSnapshot', '{}'::jsonb),\n        child_val->>'orderType',\n        child_val->>'orderSource',\n        child_val->>'createdBy',\n        child_val->>'createdByRole',\n        child_val->'proxyExecutor',\n        child_val->>'printerCategory',\n        child_val->'amounts',\n        child_val->'delivery',\n        child_val->'workflow',\n        child_val->'workflowSnapshot',\n        child_val->>'currentWorkflowRole',\n        child_val->>'currentWorkflowLabel',\n        child_val->>'productionNotes',\n        child_val->>'thumbnailUrl',\n        child_val->>'productName',\n        child_val->>'description',\n        COALESCE(child_val->'items', '[]'::jsonb),\n        child_val->>'status',\n        child_val->>'paymentStatus',\n        COALESCE(child_val->'createdAt', to_jsonb(NOW()::text)),\n        COALESCE(child_val->'updatedAt', to_jsonb(NOW()::text)),\n        child_val->>'shippingAddress',\n        child_val->>'deliveryChoice'\n      );\n    END LOOP;\n  END IF;\n\n  -- 6. Insert Order Items into order_items table (Batch)\n  IF p_order_items IS NOT NULL THEN\n    FOREACH item_val IN ARRAY p_order_items LOOP\n      INSERT INTO order_items (\n        id, order_id, product_name, product_id, category, project_name, specs, material_metadata,\n        pricing_snapshot, file_url, design_url, design_status, design_upload_stats,\n        \\"assignedPrinterId\\", \\"assignedPrinterName\\", \\"fileUrl\\", \\"productId\\", \\"productName\\",\n        \\"projectName\\", \\"materialMetadata\\", \\"pricingSnapshot\\", \\"designUrl\\", \\"designStatus\\",\n        \\"designUploadStats\\", description, \\"designType\\", \\"itemWorkspace\\", created_at, updated_at\n      ) VALUES (\n        item_val->>'id',\n        item_val->>'orderId',\n        item_val->>'productName',\n        item_val->>'productId',\n        item_val->>'category',\n        item_val->>'projectName',\n        COALESCE(item_val->'specs', '{}'::jsonb),\n        COALESCE(item_val->'materialMetadata', '{}'::jsonb),\n        COALESCE(item_val->'pricingSnapshot', '{}'::jsonb),\n        item_val->>'fileUrl',\n        item_val->>'designUrl',\n        item_val->>'designStatus',\n        COALESCE(item_val->'designUploadStats', '{}'::jsonb),\n        item_val->>'assignedPrinterId',\n        item_val->>'assignedPrinterName',\n        item_val->>'fileUrl',\n        item_val->>'productId',\n        item_val->>'productName',\n        item_val->>'projectName',\n        COALESCE(item_val->'materialMetadata', '{}'::jsonb),\n        COALESCE(item_val->'pricingSnapshot', '{}'::jsonb),\n        item_val->>'designUrl',\n        item_val->>'designStatus',\n        COALESCE(item_val->'designUploadStats', '{}'::jsonb),\n        item_val->>'description',\n        item_val->>'designType',\n        COALESCE(item_val->'itemWorkspace', '{}'::jsonb),\n        NOW(),\n        NOW()\n      );\n    END LOOP;\n  END IF;\n\n  -- 7. Insert Ledger Entries into transactions table (Batch)\n  IF p_ledger_entries IS NOT NULL THEN\n    FOREACH ledger_val IN ARRAY p_ledger_entries LOOP\n      INSERT INTO transactions (\n        id, \\"userId\\", type, \\"ledgerType\\", \\"refId\\", debit, credit, \\"balanceBefore\\", \\"balanceAfter\\",\n        \\"availableCredit\\", remarks, \\"createdBy\\", timestamp, \\"isVerified\\", \\"verifiedAt\\", \\"verifiedBy\\",\n        \\"paymentId\\"\n      ) VALUES (\n        ledger_val->>'id',\n        ledger_val->>'userId',\n        ledger_val->>'type',\n        ledger_val->>'ledgerType',\n        ledger_val->>'refId',\n        COALESCE((ledger_val->>'debit')::numeric, 0),\n        COALESCE((ledger_val->>'credit')::numeric, 0),\n        COALESCE((ledger_val->>'balanceBefore')::numeric, 0),\n        COALESCE((ledger_val->>'balanceAfter')::numeric, 0),\n        COALESCE((ledger_val->>'availableCredit')::numeric, 0),\n        ledger_val->>'remarks',\n        ledger_val->>'createdBy',\n        to_jsonb(NOW()::text),\n        COALESCE((ledger_val->>'isVerified')::boolean, false),\n        CASE WHEN ledger_val->>'verifiedAt' IS NOT NULL THEN to_jsonb(ledger_val->>'verifiedAt') ELSE NULL END,\n        ledger_val->>'verifiedBy',\n        ledger_val->>'paymentId'\n      );\n    END LOOP;\n  END IF;\n\n  -- 8. Insert Background Jobs into document_jobs table (Batch)\n  IF p_jobs IS NOT NULL THEN\n    FOREACH job_val IN ARRAY p_jobs LOOP\n      INSERT INTO document_jobs (\n        id, \\"jobType\\", \\"orderId\\", \\"parentOrderId\\", priority, status, \\"createdAt\\", \\"payload\\"\n      ) VALUES (\n        job_val->>'jobId',\n        job_val->>'jobType',\n        job_val->>'orderId',\n        p_parent_order->>'id',\n        COALESCE((job_val->>'priority')::integer, 2),\n        'PENDING',\n        NOW(),\n        COALESCE(job_val->'payload', '{}'::jsonb)\n      );\n    END LOOP;\n  END IF;\n\n  v_result := jsonb_build_object(\n    'success', true,\n    'orderId', p_parent_order->>'id',\n    'balanceBefore', v_used_credit,\n    'balanceAfter', v_new_used_credit\n  );\n  \n  RETURN v_result;\nEND;\n$$","-- Atomic transaction RPC function to generate the tax invoice, locking the parent order and preventing duplication\nCREATE OR REPLACE FUNCTION generate_invoice_tx(\n  p_parent_order_id text,\n  p_invoice_id text,\n  p_invoice_number text,\n  p_child_ids text[],\n  p_customer_id text,\n  p_customer_snapshot jsonb,\n  p_items jsonb,\n  p_amounts jsonb,\n  p_order_type text,\n  p_payment_status text\n) RETURNS jsonb LANGUAGE plpgsql AS $$\nDECLARE\n  v_exists boolean;\n  v_result jsonb;\nBEGIN\n  -- 1. Lock the parent order row\n  PERFORM 1 FROM orders WHERE id = p_parent_order_id FOR UPDATE;\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Parent order % not found', p_parent_order_id;\n  END IF;\n\n  -- 2. Check again if invoice already exists\n  SELECT EXISTS(SELECT 1 FROM invoices WHERE \\"parentOrderId\\" = p_parent_order_id) INTO v_exists;\n  IF v_exists THEN\n    RETURN jsonb_build_object('success', false, 'reason', 'ALREADY_EXISTS');\n  END IF;\n\n  -- 3. Generate the invoice record\n  INSERT INTO invoices (\n    id, \\"invoiceNumber\\", \\"parentOrderId\\", \\"childOrderIds\\", \\"customerId\\",\n    \\"customerSnapshot\\", items, amounts, status, \\"generatedBy\\",\n    \\"orderType\\", \\"paymentStatus\\", \\"createdAt\\", \\"updatedAt\\"\n  ) VALUES (\n    p_invoice_id,\n    p_invoice_number,\n    p_parent_order_id,\n    p_child_ids,\n    p_customer_id,\n    p_customer_snapshot,\n    p_items,\n    p_amounts,\n    'ACTIVE',\n    'SYSTEM',\n    p_order_type,\n    p_payment_status,\n    NOW(),\n    NOW()\n  );\n\n  -- 4. Set invoiceNumber on Parent Order\n  UPDATE orders\n  SET \\"invoiceNumber\\" = p_invoice_number, \\"updatedAt\\" = to_jsonb(NOW()::text)\n  WHERE id = p_parent_order_id;\n\n  v_result := jsonb_build_object('success', true);\n  RETURN v_result;\nEND;\n$$"}	migrate_job_queue_camelcase
20260616150000	{"-- SQL Migration: Add idempotency_keys table and update place_order_tx\n-- Establishes database-level idempotency checks inside the placement transaction.\n\nCREATE TABLE IF NOT EXISTS public.idempotency_keys (\n    idempotency_key TEXT PRIMARY KEY,\n    order_id TEXT NOT NULL,\n    created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()\n)","-- Drop the previous version of the function to allow changing signature (adding p_idempotency_key parameter)\nDROP FUNCTION IF EXISTS place_order_tx(\n  p_customer_id text,\n  p_order_type text,\n  p_grand_total numeric,\n  p_parent_order jsonb,\n  p_child_orders jsonb[],\n  p_order_items jsonb[],\n  p_ledger_entries jsonb[],\n  p_jobs jsonb[]\n)","-- Recreate place_order_tx with p_idempotency_key parameter\nCREATE OR REPLACE FUNCTION place_order_tx(\n  p_customer_id text,\n  p_order_type text,\n  p_grand_total numeric,\n  p_parent_order jsonb,\n  p_child_orders jsonb[],\n  p_order_items jsonb[],\n  p_ledger_entries jsonb[],\n  p_jobs jsonb[],\n  p_idempotency_key text\n) RETURNS jsonb LANGUAGE plpgsql AS $$\nDECLARE\n  v_used_credit numeric;\n  v_credit_limit numeric;\n  v_new_used_credit numeric;\n  child_val jsonb;\n  item_val jsonb;\n  ledger_val jsonb;\n  job_val jsonb;\n  v_result jsonb;\n  v_exists boolean;\nBEGIN\n  -- 1. Idempotency Check\n  IF p_idempotency_key IS NOT NULL THEN\n    SELECT EXISTS(SELECT 1 FROM idempotency_keys WHERE idempotency_key = p_idempotency_key) INTO v_exists;\n    IF v_exists THEN\n      -- Retrieve the existing order ID corresponding to this idempotency key\n      SELECT order_id INTO v_result FROM idempotency_keys WHERE idempotency_key = p_idempotency_key;\n      RETURN jsonb_build_object(\n        'success', true,\n        'orderId', v_result,\n        'duplicate', true\n      );\n    END IF;\n  END IF;\n\n  -- 2. Read and Lock Customer Profile Row\n  SELECT COALESCE(\\"usedCredit\\", 0), COALESCE(\\"creditLimit\\", 0)\n  INTO v_used_credit, v_credit_limit\n  FROM profiles\n  WHERE id = p_customer_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Customer profile not found for ID %', p_customer_id;\n  END IF;\n\n  -- 3. Validate Credit Limit (if CREDIT customer)\n  IF p_order_type = 'CREDIT' THEN\n    IF (v_used_credit + p_grand_total) > v_credit_limit THEN\n      RAISE EXCEPTION 'Credit limit exceeded. Current used: %, Limit: %, Requested: %', v_used_credit, v_credit_limit, p_grand_total;\n    END IF;\n  END IF;\n\n  -- 4. Update Locked Customer Used Credit Balance\n  v_new_used_credit := v_used_credit + p_grand_total;\n  UPDATE profiles\n  SET \\"usedCredit\\" = v_new_used_credit, \\"updatedAt\\" = to_jsonb(NOW()::text)\n  WHERE id = p_customer_id;\n\n  -- 5. Insert Parent Order (if provided)\n  IF p_parent_order IS NOT NULL THEN\n    INSERT INTO orders (\n      id, \\"customerId\\", \\"customerName\\", \\"customerSnapshot\\", \\"orderType\\", \\"orderSource\\",\n      \\"createdBy\\", \\"createdByRole\\", \\"proxyExecutor\\", \\"printerCategory\\", amounts, delivery,\n      workflow, \\"workflowSnapshot\\", \\"currentWorkflowRole\\", \\"currentWorkflowLabel\\",\n      \\"productionNotes\\", \\"thumbnailUrl\\", \\"productName\\", \\"description\\", items, status, \\"paymentStatus\\",\n      \\"createdAt\\", \\"updatedAt\\", \\"shippingAddress\\", \\"deliveryChoice\\"\n    ) VALUES (\n      p_parent_order->>'id',\n      p_parent_order->>'customerId',\n      p_parent_order->>'customerName',\n      COALESCE(p_parent_order->'customerSnapshot', '{}'::jsonb),\n      p_parent_order->>'orderType',\n      p_parent_order->>'orderSource',\n      p_parent_order->>'createdBy',\n      p_parent_order->>'createdByRole',\n      p_parent_order->'proxyExecutor',\n      p_parent_order->>'printerCategory',\n      p_parent_order->'amounts',\n      p_parent_order->'delivery',\n      p_parent_order->'workflow',\n      p_parent_order->'workflowSnapshot',\n      p_parent_order->>'currentWorkflowRole',\n      p_parent_order->>'currentWorkflowLabel',\n      p_parent_order->>'productionNotes',\n      p_parent_order->>'thumbnailUrl',\n      p_parent_order->>'productName',\n      p_parent_order->>'description',\n      COALESCE(p_parent_order->'items', '[]'::jsonb),\n      p_parent_order->>'status',\n      p_parent_order->>'paymentStatus',\n      COALESCE(p_parent_order->'createdAt', to_jsonb(NOW()::text)),\n      COALESCE(p_parent_order->'updatedAt', to_jsonb(NOW()::text)),\n      p_parent_order->>'shippingAddress',\n      p_parent_order->>'deliveryChoice'\n    );\n  END IF;\n\n  -- 6. Insert Child Orders (Batch)\n  IF p_child_orders IS NOT NULL THEN\n    FOREACH child_val IN ARRAY p_child_orders LOOP\n      INSERT INTO orders (\n        id, \\"customerId\\", \\"customerName\\", \\"customerSnapshot\\", \\"orderType\\", \\"orderSource\\",\n        \\"createdBy\\", \\"createdByRole\\", \\"proxyExecutor\\", \\"printerCategory\\", amounts, delivery,\n        workflow, \\"workflowSnapshot\\", \\"currentWorkflowRole\\", \\"currentWorkflowLabel\\",\n        \\"productionNotes\\", \\"thumbnailUrl\\", \\"productName\\", \\"description\\", items, status, \\"paymentStatus\\",\n        \\"createdAt\\", \\"updatedAt\\", \\"shippingAddress\\", \\"deliveryChoice\\"\n      ) VALUES (\n        child_val->>'id',\n        child_val->>'customerId',\n        child_val->>'customerName',\n        COALESCE(child_val->'customerSnapshot', '{}'::jsonb),\n        child_val->>'orderType',\n        child_val->>'orderSource',\n        child_val->>'createdBy',\n        child_val->>'createdByRole',\n        child_val->'proxyExecutor',\n        child_val->>'printerCategory',\n        child_val->'amounts',\n        child_val->'delivery',\n        child_val->'workflow',\n        child_val->'workflowSnapshot',\n        child_val->>'currentWorkflowRole',\n        child_val->>'currentWorkflowLabel',\n        child_val->>'productionNotes',\n        child_val->>'thumbnailUrl',\n        child_val->>'productName',\n        child_val->>'description',\n        COALESCE(child_val->'items', '[]'::jsonb),\n        child_val->>'status',\n        child_val->>'paymentStatus',\n        COALESCE(child_val->'createdAt', to_jsonb(NOW()::text)),\n        COALESCE(child_val->'updatedAt', to_jsonb(NOW()::text)),\n        child_val->>'shippingAddress',\n        child_val->>'deliveryChoice'\n      );\n    END LOOP;\n  END IF;\n\n  -- 7. Insert Order Items into order_items table (Batch)\n  IF p_order_items IS NOT NULL THEN\n    FOREACH item_val IN ARRAY p_order_items LOOP\n      INSERT INTO order_items (\n        id, order_id, product_name, product_id, category, project_name, specs, material_metadata,\n        pricing_snapshot, file_url, design_url, design_status, design_upload_stats,\n        \\"assignedPrinterId\\", \\"assignedPrinterName\\", \\"fileUrl\\", \\"productId\\", \\"productName\\",\n        \\"projectName\\", \\"materialMetadata\\", \\"pricingSnapshot\\", \\"designUrl\\", \\"designStatus\\",\n        \\"designUploadStats\\", description, \\"designType\\", \\"itemWorkspace\\", created_at, updated_at\n      ) VALUES (\n        item_val->>'id',\n        item_val->>'orderId',\n        item_val->>'productName',\n        item_val->>'productId',\n        item_val->>'category',\n        item_val->>'projectName',\n        COALESCE(item_val->'specs', '{}'::jsonb),\n        COALESCE(item_val->'materialMetadata', '{}'::jsonb),\n        COALESCE(item_val->'pricingSnapshot', '{}'::jsonb),\n        item_val->>'fileUrl',\n        item_val->>'designUrl',\n        item_val->>'designStatus',\n        COALESCE(item_val->'designUploadStats', '{}'::jsonb),\n        item_val->>'assignedPrinterId',\n        item_val->>'assignedPrinterName',\n        item_val->>'fileUrl',\n        item_val->>'productId',\n        item_val->>'productName',\n        item_val->>'projectName',\n        COALESCE(item_val->'materialMetadata', '{}'::jsonb),\n        COALESCE(item_val->'pricingSnapshot', '{}'::jsonb),\n        item_val->>'designUrl',\n        item_val->>'designStatus',\n        COALESCE(item_val->'designUploadStats', '{}'::jsonb),\n        item_val->>'description',\n        item_val->>'designType',\n        COALESCE(item_val->'itemWorkspace', '{}'::jsonb),\n        NOW(),\n        NOW()\n      );\n    END LOOP;\n  END IF;\n\n  -- 8. Insert Ledger Entries into transactions table (Batch)\n  IF p_ledger_entries IS NOT NULL THEN\n    FOREACH ledger_val IN ARRAY p_ledger_entries LOOP\n      INSERT INTO transactions (\n        id, \\"userId\\", type, \\"ledgerType\\", \\"refId\\", debit, credit, \\"balanceBefore\\", \\"balanceAfter\\",\n        \\"availableCredit\\", remarks, \\"createdBy\\", timestamp, \\"isVerified\\", \\"verifiedAt\\", \\"verifiedBy\\",\n        \\"paymentId\\"\n      ) VALUES (\n        ledger_val->>'id',\n        ledger_val->>'userId',\n        ledger_val->>'type',\n        ledger_val->>'ledgerType',\n        ledger_val->>'refId',\n        COALESCE((ledger_val->>'debit')::numeric, 0),\n        COALESCE((ledger_val->>'credit')::numeric, 0),\n        COALESCE((ledger_val->>'balanceBefore')::numeric, 0),\n        COALESCE((ledger_val->>'balanceAfter')::numeric, 0),\n        COALESCE((ledger_val->>'availableCredit')::numeric, 0),\n        ledger_val->>'remarks',\n        ledger_val->>'createdBy',\n        to_jsonb(NOW()::text),\n        COALESCE((ledger_val->>'isVerified')::boolean, false),\n        CASE WHEN ledger_val->>'verifiedAt' IS NOT NULL THEN to_jsonb(ledger_val->>'verifiedAt') ELSE NULL END,\n        ledger_val->>'verifiedBy',\n        ledger_val->>'paymentId'\n      );\n    END LOOP;\n  END IF;\n\n  -- 9. Insert Background Jobs into document_jobs table (Batch)\n  IF p_jobs IS NOT NULL THEN\n    FOREACH job_val IN ARRAY p_jobs LOOP\n      INSERT INTO document_jobs (\n        id, \\"jobType\\", \\"orderId\\", \\"parentOrderId\\", priority, status, \\"createdAt\\", \\"payload\\"\n      ) VALUES (\n        job_val->>'jobId',\n        job_val->>'jobType',\n        job_val->>'orderId',\n        p_parent_order->>'id',\n        COALESCE((job_val->>'priority')::integer, 2),\n        'PENDING',\n        NOW(),\n        COALESCE(job_val->'payload', '{}'::jsonb)\n      );\n    END LOOP;\n  END IF;\n\n  -- 10. Record the Idempotency Key\n  IF p_idempotency_key IS NOT NULL THEN\n    INSERT INTO idempotency_keys (idempotency_key, order_id, created_at)\n    VALUES (p_idempotency_key, p_parent_order->>'id', NOW());\n  END IF;\n\n  v_result := jsonb_build_object(\n    'success', true,\n    'orderId', p_parent_order->>'id',\n    'balanceBefore', v_used_credit,\n    'balanceAfter', v_new_used_credit\n  );\n  \n  RETURN v_result;\nEND;\n$$"}	add_idempotency_keys
20260622040000	{"-- Phase 5: RPC for atomic invoice generation\r\n\r\nCREATE OR REPLACE FUNCTION public.get_financial_year(p_date DATE) RETURNS TEXT AS $$\r\nDECLARE\r\n  v_year INTEGER := extract(year from p_date);\r\n  v_month INTEGER := extract(month from p_date);\r\n  v_next_year INTEGER;\r\nBEGIN\r\n  IF v_month < 4 THEN\r\n    v_next_year := v_year;\r\n    v_year := v_year - 1;\r\n  ELSE\r\n    v_next_year := v_year + 1;\r\n  END IF;\r\n  RETURN v_year::TEXT || '-' || right(v_next_year::TEXT, 2);\r\nEND;\r\n$$ LANGUAGE plpgsql IMMUTABLE","CREATE OR REPLACE FUNCTION public.reserve_invoice_number(p_invoice_date DATE)\r\nRETURNS TABLE (\r\n  invoice_number TEXT,\r\n  invoice_sequence INTEGER,\r\n  financial_year TEXT\r\n) AS $$\r\nDECLARE\r\n  v_fy TEXT;\r\n  v_prefix TEXT;\r\n  v_separator TEXT;\r\n  v_padding INTEGER;\r\n  v_seq INTEGER;\r\n  v_is_locked BOOLEAN;\r\n  v_inv_num TEXT;\r\nBEGIN\r\n  v_fy := public.get_financial_year(p_invoice_date);\r\n\r\n  -- Lock the row for update\r\n  SELECT prefix, last_number, is_locked \r\n  INTO v_prefix, v_seq, v_is_locked\r\n  FROM public.invoice_sequences\r\n  WHERE public.invoice_sequences.financial_year = v_fy\r\n  FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    -- Auto-create sequence for new FY if it doesn't exist\r\n    INSERT INTO public.invoice_sequences (financial_year, prefix, separator, padding_length, last_number)\r\n    VALUES (v_fy, 'HE/', 0)\r\n    RETURNING prefix, last_number, is_locked\r\n    INTO v_prefix, v_seq, v_is_locked;\r\n  END IF;\r\n\r\n  IF v_is_locked THEN\r\n    RAISE EXCEPTION 'Financial year % is locked. Cannot generate invoices.', v_fy;\r\n  END IF;\r\n\r\n  v_seq := v_seq + 1;\r\n\r\n  UPDATE public.invoice_sequences\r\n  SET last_number = v_seq, updated_at = now()\r\n  WHERE public.invoice_sequences.financial_year = v_fy;\r\n\r\n  v_inv_num := v_prefix || v_fy || '/' || lpad(v_seq::TEXT, 6, '0');\r\n\r\n  RETURN QUERY SELECT v_inv_num, v_seq, v_fy;\r\nEND;\r\n$$ LANGUAGE plpgsql","-- Also we need an RPC to insert the invoice atomically if we don't want to do multiple roundtrips,\r\n-- but since we just need the number, returning the number is fine. We can just insert it from TS."}	phase5_invoice_rpc_fix2
20260616160000	{"-- SQL Migration: Phase 5 Production Hardening\n-- Creates tables and functions for Postgres-backed rate limiting, auditing metadata, immutability, optimistic locking, worker health, and notifications logging.\n\n-- 1. Rate Limiting Schema\nCREATE TABLE IF NOT EXISTS public.rate_limits (\n    key TEXT PRIMARY KEY,\n    hits INTEGER NOT NULL DEFAULT 1,\n    reset_at TIMESTAMP WITH TIME ZONE NOT NULL\n)","CREATE OR REPLACE FUNCTION public.increment_rate_limit(\n    p_key TEXT,\n    p_limit INTEGER,\n    p_window_interval INTERVAL\n) RETURNS JSONB AS $$\nDECLARE\n    v_hits INTEGER;\n    v_reset_at TIMESTAMP WITH TIME ZONE;\n    v_now TIMESTAMP WITH TIME ZONE := NOW();\nBEGIN\n    SELECT hits, reset_at INTO v_hits, v_reset_at FROM public.rate_limits WHERE key = p_key;\n    IF NOT FOUND OR v_now > v_reset_at THEN\n        v_reset_at := v_now + p_window_interval;\n        INSERT INTO public.rate_limits (key, hits, reset_at)\n        VALUES (p_key, 1, v_reset_at)\n        ON CONFLICT (key) DO UPDATE\n        SET hits = 1, reset_at = v_reset_at;\n        RETURN jsonb_build_object('allowed', TRUE, 'remaining', p_limit - 1, 'reset_at', v_reset_at);\n    END IF;\n\n    IF v_hits >= p_limit THEN\n        RETURN jsonb_build_object('allowed', FALSE, 'remaining', 0, 'reset_at', v_reset_at);\n    END IF;\n\n    UPDATE public.rate_limits SET hits = hits + 1 WHERE key = p_key RETURNING hits INTO v_hits;\n    RETURN jsonb_build_object('allowed', TRUE, 'remaining', p_limit - v_hits, 'reset_at', v_reset_at);\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER","-- 2. Optimistic Locking Column\nALTER TABLE public.orders ADD COLUMN IF NOT EXISTS version INTEGER NOT NULL DEFAULT 1","-- 3. Audit Log Enhancements & Immutability Triggers\nALTER TABLE public.audit_logs \n    ADD COLUMN IF NOT EXISTS actor_role TEXT,\n    ADD COLUMN IF NOT EXISTS ip_address TEXT,\n    ADD COLUMN IF NOT EXISTS user_agent TEXT,\n    ADD COLUMN IF NOT EXISTS session_id TEXT,\n    ADD COLUMN IF NOT EXISTS request_id TEXT,\n    ADD COLUMN IF NOT EXISTS previous_value JSONB,\n    ADD COLUMN IF NOT EXISTS new_value JSONB","CREATE OR REPLACE FUNCTION public.protect_audit_logs() RETURNS TRIGGER AS $$\nBEGIN\n    RAISE EXCEPTION 'Audit logs are immutable. No updates or deletes allowed.';\nEND;\n$$ LANGUAGE plpgsql","DROP TRIGGER IF EXISTS enforce_immutable_audit_logs ON public.audit_logs","CREATE TRIGGER enforce_immutable_audit_logs\n    BEFORE UPDATE OR DELETE ON public.audit_logs\n    FOR EACH ROW EXECUTE FUNCTION public.protect_audit_logs()","-- 4. Worker Monitoring Schema\nCREATE TABLE IF NOT EXISTS public.worker_health (\n    worker_id TEXT PRIMARY KEY,\n    status TEXT NOT NULL, -- 'IDLE' | 'RUNNING' | 'FAILED'\n    last_run TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),\n    last_success TIMESTAMP WITH TIME ZONE,\n    last_failure TIMESTAMP WITH TIME ZONE,\n    current_job TEXT,\n    avg_runtime NUMERIC DEFAULT 0,\n    retry_count INTEGER DEFAULT 0,\n    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW()\n)","-- 5. Notifications Logging Schema\nCREATE TABLE IF NOT EXISTS public.notifications_log (\n    id TEXT PRIMARY KEY,\n    user_id TEXT REFERENCES public.profiles(id) ON DELETE SET NULL,\n    channel TEXT NOT NULL, -- 'EMAIL' | 'SMS' | 'WHATSAPP' | 'PUSH' | 'IN_APP'\n    title TEXT NOT NULL,\n    body TEXT NOT NULL,\n    status TEXT NOT NULL, -- 'SENT' | 'DELIVERED' | 'FAILED' | 'RETRYING'\n    retry_count INTEGER NOT NULL DEFAULT 0,\n    delivery_time TIMESTAMP WITH TIME ZONE,\n    error_message TEXT,\n    metadata JSONB NOT NULL DEFAULT '{}'::jsonb,\n    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW(),\n    updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT NOW()\n)"}	phase5_hardening
20260618000000	{"-- ============================================================\n-- GST Tax Invoice System Migration\n-- ============================================================\n\n-- 1. tax_templates – single source of truth for company/GST/bank settings\nCREATE TABLE IF NOT EXISTS public.tax_templates (\n  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  -- Company Information\n  company_name  text NOT NULL DEFAULT 'Hindustan Enterprises',\n  address       text NOT NULL DEFAULT '#1, New Bamboo Bazaar',\n  city          text NOT NULL DEFAULT 'Mysore',\n  state         text NOT NULL DEFAULT 'Karnataka',\n  state_code    text NOT NULL DEFAULT '29',\n  pincode       text NOT NULL DEFAULT '570001',\n  phone         text NOT NULL DEFAULT '+91 90007 76007',\n  email         text NOT NULL DEFAULT 'info@hindustanenterprises.com',\n  website       text,\n  -- GST & Tax\n  gstin         text NOT NULL DEFAULT '29AFHPP0687G1Z2',\n  pan           text NOT NULL DEFAULT 'AFHPP0687G',\n  msme_reg      text,\n  -- Bank Details\n  bank_name     text NOT NULL DEFAULT 'ICICI Bank',\n  branch        text NOT NULL DEFAULT 'Mysore Main',\n  account_number text NOT NULL DEFAULT '6255505013373',\n  ifsc          text NOT NULL DEFAULT 'ICIC0006255',\n  beneficiary_name text NOT NULL DEFAULT 'Hindustan Enterprises',\n  upi_id        text,\n  -- Invoice Settings\n  invoice_prefix text NOT NULL DEFAULT 'HE',\n  default_gst   numeric(5,2) NOT NULL DEFAULT 18.00,\n  round_off     boolean NOT NULL DEFAULT true,\n  auto_qr       boolean NOT NULL DEFAULT false,\n  amount_in_words boolean NOT NULL DEFAULT true,\n  -- Assets (Cloudinary / public URLs)\n  logo_url      text,\n  signature_url text,\n  seal_url      text,\n  -- Footer & Legal\n  declaration   text NOT NULL DEFAULT 'We declare that this invoice shows the actual price of the goods described and that all particulars are true and correct.',\n  terms         text NOT NULL DEFAULT '1. Interest @ 24% PA + taxes applicable if payment not made within the stipulated time\\\\n2. We are not responsible for Damages, Shortages which occur during transit',\n  footer_text   text NOT NULL DEFAULT 'This is a Computer Generated Invoice',\n  -- Meta\n  is_active     boolean NOT NULL DEFAULT true,\n  created_at    timestamptz NOT NULL DEFAULT now(),\n  updated_at    timestamptz NOT NULL DEFAULT now()\n)","-- Seed default company details\nINSERT INTO public.tax_templates (\n  company_name, address, city, state, state_code, pincode,\n  phone, email, gstin, pan, bank_name, branch, account_number,\n  ifsc, beneficiary_name, invoice_prefix, default_gst, round_off,\n  declaration, terms, footer_text\n) VALUES (\n  'Hindustan Enterprises',\n  '#1, New Bamboo Bazaar',\n  'Mysore',\n  'Karnataka',\n  '29',\n  '570001',\n  '+91 90007 76007',\n  'info@hindustanenterprises.com',\n  '29AFHPP0687G1Z2',\n  'AFHPP0687G',\n  'ICICI Bank',\n  'Mysore Main',\n  '6255505013373',\n  'ICIC0006255',\n  'Hindustan Enterprises',\n  'HE',\n  18.00,\n  true,\n  'We declare that this invoice shows the actual price of the goods described and that all particulars are true and correct.',\n  E'1. Interest @ 24% PA + taxes applicable if payment not made within the stipulated time\\\\n2. We are not responsible for Damages, Shortages which occur during transit',\n  'This is a Computer Generated Invoice'\n) ON CONFLICT DO NOTHING","-- Enable RLS\nALTER TABLE public.tax_templates ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"Admin can manage tax_templates\\" ON public.tax_templates FOR ALL USING (true)","-- 2. dispatch_details – dedicated table for transport info, keeps orders clean\nCREATE TABLE IF NOT EXISTS public.dispatch_details (\n  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  parent_order_id    text NOT NULL UNIQUE,\n  transporter_name   text,\n  dispatch_through   text,\n  lr_number          text,\n  lr_date            date,\n  vehicle_number     text,\n  destination        text,\n  delivery_note      text,\n  delivery_note_date date,\n  created_by         uuid,\n  created_at         timestamptz NOT NULL DEFAULT now(),\n  updated_at         timestamptz NOT NULL DEFAULT now()\n)","ALTER TABLE public.dispatch_details ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"Staff can manage dispatch_details\\" ON public.dispatch_details FOR ALL USING (true)","-- 3. invoices table with full status lifecycle + idempotency constraint\nCREATE TABLE IF NOT EXISTS public.invoices (\n  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  invoice_number   text UNIQUE,\n  parent_order_id  text NOT NULL UNIQUE, -- UNIQUE: one invoice per parent order\n  customer_id      text,\n  -- Snapshot of invoice data at generation time\n  invoice_data     jsonb NOT NULL DEFAULT '{}',\n  -- Status lifecycle: Draft → Queued → Generating → Generated → Cancelled / Regenerated\n  status           text NOT NULL DEFAULT 'Draft'\n                     CHECK (status IN ('Draft','Queued','Generating','Generated','Cancelled','Regenerated')),\n  -- PDF storage\n  pdf_url          text,\n  -- Tax template snapshot (which template version was used)\n  tax_template_id  uuid REFERENCES public.tax_templates(id),\n  -- Job queue reference\n  job_id           uuid,\n  -- Error tracking\n  error_message    text,\n  retry_count      int NOT NULL DEFAULT 0,\n  -- Timestamps\n  queued_at        timestamptz,\n  generated_at     timestamptz,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  updated_at       timestamptz NOT NULL DEFAULT now()\n)","ALTER TABLE public.invoices ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"Admin can manage invoices\\" ON public.invoices FOR ALL USING (true)","-- 4. Expand profiles table with GST / billing / shipping / business fields\nALTER TABLE public.profiles\n  ADD COLUMN IF NOT EXISTS company_name          text,\n  ADD COLUMN IF NOT EXISTS contact_person        text,\n  ADD COLUMN IF NOT EXISTS alternate_mobile      text,\n  ADD COLUMN IF NOT EXISTS gst_registered        boolean NOT NULL DEFAULT false,\n  ADD COLUMN IF NOT EXISTS gstin                 text,\n  ADD COLUMN IF NOT EXISTS pan_number            text,\n  ADD COLUMN IF NOT EXISTS customer_code         text,\n  -- Billing Address\n  ADD COLUMN IF NOT EXISTS billing_address_line1 text,\n  ADD COLUMN IF NOT EXISTS billing_address_line2 text,\n  ADD COLUMN IF NOT EXISTS billing_area          text,\n  ADD COLUMN IF NOT EXISTS billing_city          text,\n  ADD COLUMN IF NOT EXISTS billing_district      text,\n  ADD COLUMN IF NOT EXISTS billing_state         text,\n  ADD COLUMN IF NOT EXISTS billing_state_code    text,\n  ADD COLUMN IF NOT EXISTS billing_pincode       text,\n  ADD COLUMN IF NOT EXISTS billing_country       text NOT NULL DEFAULT 'India',\n  -- Shipping / Consignee Address\n  ADD COLUMN IF NOT EXISTS shipping_same_as_billing boolean NOT NULL DEFAULT true,\n  ADD COLUMN IF NOT EXISTS consignee_name        text,\n  ADD COLUMN IF NOT EXISTS consignee_contact     text,\n  ADD COLUMN IF NOT EXISTS consignee_mobile      text,\n  ADD COLUMN IF NOT EXISTS consignee_gstin       text,\n  ADD COLUMN IF NOT EXISTS shipping_address_line1 text,\n  ADD COLUMN IF NOT EXISTS shipping_address_line2 text,\n  ADD COLUMN IF NOT EXISTS shipping_area         text,\n  ADD COLUMN IF NOT EXISTS shipping_city         text,\n  ADD COLUMN IF NOT EXISTS shipping_district     text,\n  ADD COLUMN IF NOT EXISTS shipping_state        text,\n  ADD COLUMN IF NOT EXISTS shipping_state_code   text,\n  ADD COLUMN IF NOT EXISTS shipping_pincode      text,\n  ADD COLUMN IF NOT EXISTS shipping_country      text NOT NULL DEFAULT 'India',\n  -- Business Terms\n  ADD COLUMN IF NOT EXISTS payment_terms         text,\n  ADD COLUMN IF NOT EXISTS credit_days           int,\n  ADD COLUMN IF NOT EXISTS preferred_transporter text,\n  ADD COLUMN IF NOT EXISTS remarks               text"}	gst_invoice_system
20260619113200	{"-- SQL Migration: Optimize place_order_tx with set-based operations\n-- Replaces FOREACH loops with unnest() for improved performance on bulk inserts.\n-- Consolidates NOW() calls into a single timestamp to avoid multiple clock reads.\n\nCREATE OR REPLACE FUNCTION place_order_tx(\n  p_customer_id text,\n  p_order_type text,\n  p_grand_total numeric,\n  p_parent_order jsonb,\n  p_child_orders jsonb[],\n  p_order_items jsonb[],\n  p_ledger_entries jsonb[],\n  p_jobs jsonb[],\n  p_idempotency_key text\n) RETURNS jsonb LANGUAGE plpgsql AS $$\nDECLARE\n  v_used_credit numeric;\n  v_credit_limit numeric;\n  v_new_used_credit numeric;\n  v_result jsonb;\n  v_exists boolean;\n  v_now timestamp with time zone := NOW();\n  v_now_json jsonb := to_jsonb(v_now::text);\nBEGIN\n  -- 1. Idempotency Check\n  IF p_idempotency_key IS NOT NULL THEN\n    SELECT EXISTS(SELECT 1 FROM idempotency_keys WHERE idempotency_key = p_idempotency_key) INTO v_exists;\n    IF v_exists THEN\n      -- Retrieve the existing order ID corresponding to this idempotency key\n      SELECT order_id INTO v_result FROM idempotency_keys WHERE idempotency_key = p_idempotency_key;\n      RETURN jsonb_build_object(\n        'success', true,\n        'orderId', v_result,\n        'duplicate', true\n      );\n    END IF;\n  END IF;\n\n  -- 2. Read and Lock Customer Profile Row\n  SELECT COALESCE(\\"usedCredit\\", 0), COALESCE(\\"creditLimit\\", 0)\n  INTO v_used_credit, v_credit_limit\n  FROM profiles\n  WHERE id = p_customer_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Customer profile not found for ID %', p_customer_id;\n  END IF;\n\n  -- 3. Validate Credit Limit (if CREDIT customer)\n  IF p_order_type = 'CREDIT' THEN\n    IF (v_used_credit + p_grand_total) > v_credit_limit THEN\n      RAISE EXCEPTION 'Credit limit exceeded. Current used: %, Limit: %, Requested: %', v_used_credit, v_credit_limit, p_grand_total;\n    END IF;\n  END IF;\n\n  -- 4. Update Locked Customer Used Credit Balance\n  v_new_used_credit := v_used_credit + p_grand_total;\n  UPDATE profiles\n  SET \\"usedCredit\\" = v_new_used_credit, \\"updatedAt\\" = v_now_json\n  WHERE id = p_customer_id;\n\n  -- 5. Insert Parent Order (if provided)\n  IF p_parent_order IS NOT NULL THEN\n    INSERT INTO orders (\n      id, \\"customerId\\", \\"customerName\\", \\"customerSnapshot\\", \\"orderType\\", \\"orderSource\\",\n      \\"createdBy\\", \\"createdByRole\\", \\"proxyExecutor\\", \\"printerCategory\\", amounts, delivery,\n      workflow, \\"workflowSnapshot\\", \\"currentWorkflowRole\\", \\"currentWorkflowLabel\\",\n      \\"productionNotes\\", \\"thumbnailUrl\\", \\"productName\\", \\"description\\", items, status, \\"paymentStatus\\",\n      \\"createdAt\\", \\"updatedAt\\", \\"shippingAddress\\", \\"deliveryChoice\\"\n    ) VALUES (\n      p_parent_order->>'id',\n      p_parent_order->>'customerId',\n      p_parent_order->>'customerName',\n      COALESCE(p_parent_order->'customerSnapshot', '{}'::jsonb),\n      p_parent_order->>'orderType',\n      p_parent_order->>'orderSource',\n      p_parent_order->>'createdBy',\n      p_parent_order->>'createdByRole',\n      p_parent_order->'proxyExecutor',\n      p_parent_order->>'printerCategory',\n      p_parent_order->'amounts',\n      p_parent_order->'delivery',\n      p_parent_order->'workflow',\n      p_parent_order->'workflowSnapshot',\n      p_parent_order->>'currentWorkflowRole',\n      p_parent_order->>'currentWorkflowLabel',\n      p_parent_order->>'productionNotes',\n      p_parent_order->>'thumbnailUrl',\n      p_parent_order->>'productName',\n      p_parent_order->>'description',\n      COALESCE(p_parent_order->'items', '[]'::jsonb),\n      p_parent_order->>'status',\n      p_parent_order->>'paymentStatus',\n      COALESCE(p_parent_order->'createdAt', v_now_json),\n      COALESCE(p_parent_order->'updatedAt', v_now_json),\n      p_parent_order->>'shippingAddress',\n      p_parent_order->>'deliveryChoice'\n    );\n  END IF;\n\n  -- 6. Insert Child Orders (Batch)\n  IF p_child_orders IS NOT NULL THEN\n    INSERT INTO orders (\n      id, \\"customerId\\", \\"customerName\\", \\"customerSnapshot\\", \\"orderType\\", \\"orderSource\\",\n      \\"createdBy\\", \\"createdByRole\\", \\"proxyExecutor\\", \\"printerCategory\\", amounts, delivery,\n      workflow, \\"workflowSnapshot\\", \\"currentWorkflowRole\\", \\"currentWorkflowLabel\\",\n      \\"productionNotes\\", \\"thumbnailUrl\\", \\"productName\\", \\"description\\", items, status, \\"paymentStatus\\",\n      \\"createdAt\\", \\"updatedAt\\", \\"shippingAddress\\", \\"deliveryChoice\\"\n    )\n    SELECT\n      child_val->>'id',\n      child_val->>'customerId',\n      child_val->>'customerName',\n      COALESCE(child_val->'customerSnapshot', '{}'::jsonb),\n      child_val->>'orderType',\n      child_val->>'orderSource',\n      child_val->>'createdBy',\n      child_val->>'createdByRole',\n      child_val->'proxyExecutor',\n      child_val->>'printerCategory',\n      child_val->'amounts',\n      child_val->'delivery',\n      child_val->'workflow',\n      child_val->'workflowSnapshot',\n      child_val->>'currentWorkflowRole',\n      child_val->>'currentWorkflowLabel',\n      child_val->>'productionNotes',\n      child_val->>'thumbnailUrl',\n      child_val->>'productName',\n      child_val->>'description',\n      COALESCE(child_val->'items', '[]'::jsonb),\n      child_val->>'status',\n      child_val->>'paymentStatus',\n      COALESCE(child_val->'createdAt', v_now_json),\n      COALESCE(child_val->'updatedAt', v_now_json),\n      child_val->>'shippingAddress',\n      child_val->>'deliveryChoice'\n    FROM unnest(p_child_orders) AS child_val;\n  END IF;\n\n  -- 7. Insert Order Items into order_items table (Batch)\n  IF p_order_items IS NOT NULL THEN\n    INSERT INTO order_items (\n      id, order_id, product_name, product_id, category, project_name, specs, material_metadata,\n      pricing_snapshot, file_url, design_url, design_status, design_upload_stats,\n      \\"assignedPrinterId\\", \\"assignedPrinterName\\", \\"fileUrl\\", \\"productId\\", \\"productName\\",\n      \\"projectName\\", \\"materialMetadata\\", \\"pricingSnapshot\\", \\"designUrl\\", \\"designStatus\\",\n      \\"designUploadStats\\", description, \\"designType\\", \\"itemWorkspace\\", created_at, updated_at\n    )\n    SELECT\n      item_val->>'id',\n      item_val->>'orderId',\n      item_val->>'productName',\n      item_val->>'productId',\n      item_val->>'category',\n      item_val->>'projectName',\n      COALESCE(item_val->'specs', '{}'::jsonb),\n      COALESCE(item_val->'materialMetadata', '{}'::jsonb),\n      COALESCE(item_val->'pricingSnapshot', '{}'::jsonb),\n      item_val->>'fileUrl',\n      item_val->>'designUrl',\n      item_val->>'designStatus',\n      COALESCE(item_val->'designUploadStats', '{}'::jsonb),\n      item_val->>'assignedPrinterId',\n      item_val->>'assignedPrinterName',\n      item_val->>'fileUrl',\n      item_val->>'productId',\n      item_val->>'productName',\n      item_val->>'projectName',\n      COALESCE(item_val->'materialMetadata', '{}'::jsonb),\n      COALESCE(item_val->'pricingSnapshot', '{}'::jsonb),\n      item_val->>'designUrl',\n      item_val->>'designStatus',\n      COALESCE(item_val->'designUploadStats', '{}'::jsonb),\n      item_val->>'description',\n      item_val->>'designType',\n      COALESCE(item_val->'itemWorkspace', '{}'::jsonb),\n      v_now,\n      v_now\n    FROM unnest(p_order_items) AS item_val;\n  END IF;\n\n  -- 8. Insert Ledger Entries into transactions table (Batch)\n  IF p_ledger_entries IS NOT NULL THEN\n    INSERT INTO transactions (\n      id, \\"userId\\", type, \\"ledgerType\\", \\"refId\\", debit, credit, \\"balanceBefore\\", \\"balanceAfter\\",\n      \\"availableCredit\\", remarks, \\"createdBy\\", timestamp, \\"isVerified\\", \\"verifiedAt\\", \\"verifiedBy\\",\n      \\"paymentId\\"\n    )\n    SELECT\n      ledger_val->>'id',\n      ledger_val->>'userId',\n      ledger_val->>'type',\n      ledger_val->>'ledgerType',\n      ledger_val->>'refId',\n      COALESCE((ledger_val->>'debit')::numeric, 0),\n      COALESCE((ledger_val->>'credit')::numeric, 0),\n      COALESCE((ledger_val->>'balanceBefore')::numeric, 0),\n      COALESCE((ledger_val->>'balanceAfter')::numeric, 0),\n      COALESCE((ledger_val->>'availableCredit')::numeric, 0),\n      ledger_val->>'remarks',\n      ledger_val->>'createdBy',\n      v_now_json,\n      COALESCE((ledger_val->>'isVerified')::boolean, false),\n      CASE WHEN ledger_val->>'verifiedAt' IS NOT NULL THEN to_jsonb(ledger_val->>'verifiedAt') ELSE NULL END,\n      ledger_val->>'verifiedBy',\n      ledger_val->>'paymentId'\n    FROM unnest(p_ledger_entries) AS ledger_val;\n  END IF;\n\n  -- 9. Insert Background Jobs into document_jobs table (Batch)\n  IF p_jobs IS NOT NULL THEN\n    INSERT INTO document_jobs (\n      id, \\"jobType\\", \\"orderId\\", \\"parentOrderId\\", priority, status, \\"createdAt\\", \\"payload\\"\n    )\n    SELECT\n      job_val->>'jobId',\n      job_val->>'jobType',\n      job_val->>'orderId',\n      p_parent_order->>'id',\n      COALESCE((job_val->>'priority')::integer, 2),\n      'PENDING',\n      v_now,\n      COALESCE(job_val->'payload', '{}'::jsonb)\n    FROM unnest(p_jobs) AS job_val;\n  END IF;\n\n  -- 10. Record the Idempotency Key\n  IF p_idempotency_key IS NOT NULL THEN\n    INSERT INTO idempotency_keys (idempotency_key, order_id, created_at)\n    VALUES (p_idempotency_key, p_parent_order->>'id', v_now);\n  END IF;\n\n  v_result := jsonb_build_object(\n    'success', true,\n    'orderId', p_parent_order->>'id',\n    'balanceBefore', v_used_credit,\n    'balanceAfter', v_new_used_credit\n  );\n  \n  RETURN v_result;\nEND;\n$$"}	optimize_place_order_tx
20260621231500	{"-- ============================================================\n-- Phase 1: Core Setup & HSN Master\n-- ============================================================\n\n-- 1. company_profile (Replaces tax_templates)\nCREATE TABLE IF NOT EXISTS public.company_profile (\n  id                UUID         PRIMARY KEY DEFAULT gen_random_uuid(),\n  company_name      TEXT         NOT NULL,\n  address_line1     TEXT,\n  address_line2     TEXT,\n  city              TEXT,\n  state             TEXT,\n  state_code        VARCHAR(2),\n  pincode           VARCHAR(10),\n  gstin             VARCHAR(15),\n  pan               VARCHAR(10),\n  msme_reg          TEXT,\n  phone             TEXT,\n  email             TEXT,\n  website           TEXT,\n  bank_name         TEXT,\n  account_number    TEXT,\n  ifsc              TEXT,\n  branch            TEXT,\n  beneficiary_name  TEXT,\n  upi_id            TEXT,\n  invoice_prefix    VARCHAR(10)  NOT NULL DEFAULT 'HE/',\n  declaration       TEXT,\n  terms             TEXT,\n  footer_text       TEXT,\n  logo_url          TEXT,\n  signature_url     TEXT,\n  seal_url          TEXT,\n  is_active         BOOLEAN      DEFAULT true,\n  created_at        TIMESTAMPTZ  DEFAULT now(),\n  updated_at        TIMESTAMPTZ  DEFAULT now()\n)","-- Migrate active data from tax_templates\nINSERT INTO public.company_profile (\n  company_name, address_line1, city, state, state_code, pincode, \n  phone, email, website, gstin, pan, msme_reg, \n  bank_name, branch, account_number, ifsc, beneficiary_name, upi_id, \n  invoice_prefix, declaration, terms, footer_text, logo_url, signature_url, seal_url,\n  is_active, created_at, updated_at\n)\nSELECT \n  company_name, address, city, state, state_code, pincode, \n  phone, email, website, gstin, pan, msme_reg, \n  bank_name, branch, account_number, ifsc, beneficiary_name, upi_id, \n  invoice_prefix, declaration, terms, footer_text, logo_url, signature_url, seal_url,\n  is_active, created_at, updated_at\nFROM public.tax_templates\nWHERE is_active = true\nLIMIT 1\nON CONFLICT DO NOTHING","-- 2. hsn_master\nCREATE TABLE IF NOT EXISTS public.hsn_master (\n  id                UUID         PRIMARY KEY DEFAULT gen_random_uuid(),\n  hsn_code          VARCHAR(8)   UNIQUE NOT NULL,\n  description       TEXT         NOT NULL,\n  is_active         BOOLEAN      DEFAULT true,\n  created_at        TIMESTAMPTZ  DEFAULT now(),\n  updated_at        TIMESTAMPTZ  DEFAULT now(),\n  created_by        TEXT,\n  updated_by        TEXT,\n  reason_for_change TEXT\n)","-- Trigger to prevent updating hsn_code\nCREATE OR REPLACE FUNCTION prevent_hsn_code_update()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF NEW.hsn_code <> OLD.hsn_code THEN\n    RAISE EXCEPTION 'HSN Code is immutable. Create a new HSN code instead.';\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql","CREATE TRIGGER trg_prevent_hsn_code_update\nBEFORE UPDATE ON public.hsn_master\nFOR EACH ROW EXECUTE FUNCTION prevent_hsn_code_update()","-- 3. hsn_gst_rates\nCREATE TABLE IF NOT EXISTS public.hsn_gst_rates (\n  id                UUID         PRIMARY KEY DEFAULT gen_random_uuid(),\n  hsn_id            UUID         NOT NULL REFERENCES public.hsn_master(id) ON DELETE CASCADE,\n  gst_rate          NUMERIC(5,2) NOT NULL,\n  effective_from    DATE         NOT NULL,\n  effective_to      DATE,        -- NULL means currently active\n  created_at        TIMESTAMPTZ  DEFAULT now(),\n  updated_at        TIMESTAMPTZ  DEFAULT now(),\n  created_by        TEXT,\n  updated_by        TEXT,\n  reason_for_change TEXT,\n\n  CONSTRAINT hsn_gst_rate_no_overlap UNIQUE (hsn_id, effective_from),\n  CONSTRAINT check_effective_dates CHECK (effective_to IS NULL OR effective_to >= effective_from)\n)","CREATE INDEX idx_hsn_gst_current ON public.hsn_gst_rates (hsn_id) WHERE effective_to IS NULL","-- Seed default printing HSN codes\nWITH inserted_hsns AS (\n  INSERT INTO public.hsn_master (hsn_code, description)\n  VALUES \n    ('4901', 'Printed books, brochures, leaflets and similar printed matter'),\n    ('4911', 'Other printed matter, including printed pictures and photographs'),\n    ('4819', 'Cartons, boxes, cases, bags and other packing containers'),\n    ('4820', 'Registers, account books, note books, order books, receipt books')\n  ON CONFLICT (hsn_code) DO NOTHING\n  RETURNING id, hsn_code\n)\nINSERT INTO public.hsn_gst_rates (hsn_id, gst_rate, effective_from)\nSELECT \n  ih.id, \n  CASE \n    WHEN ih.hsn_code = '4901' THEN 12.00\n    ELSE 18.00 \n  END, \n  '2017-07-01'\nFROM inserted_hsns ih","-- 3. invoice_sequences\nCREATE TABLE IF NOT EXISTS public.invoice_sequences (\n  financial_year  VARCHAR(10)  PRIMARY KEY,    -- e.g., '2026-27'\n  prefix          VARCHAR(10)  NOT NULL,       -- e.g., 'HE/'\n  last_number     INTEGER      NOT NULL DEFAULT 0,\n  is_locked       BOOLEAN      DEFAULT false,  -- If TRUE, NO generation or modifications allowed for this FY\n  created_at      TIMESTAMPTZ  DEFAULT now(),\n  updated_at      TIMESTAMPTZ  DEFAULT now()\n)","-- Seed current financial year\nINSERT INTO public.invoice_sequences (financial_year, prefix, last_number)\nVALUES ('2026-27', 'HE/', 0)\nON CONFLICT DO NOTHING","-- Add RLS Policies\nALTER TABLE public.company_profile ENABLE ROW LEVEL SECURITY","ALTER TABLE public.hsn_master ENABLE ROW LEVEL SECURITY","ALTER TABLE public.invoice_sequences ENABLE ROW LEVEL SECURITY","-- Allow authenticated users to view\nCREATE POLICY \\"Allow authenticated read company_profile\\" ON public.company_profile FOR SELECT USING (auth.role() = 'authenticated')","CREATE POLICY \\"Allow authenticated read hsn_master\\" ON public.hsn_master FOR SELECT USING (auth.role() = 'authenticated')","CREATE POLICY \\"Allow authenticated read invoice_sequences\\" ON public.invoice_sequences FOR SELECT USING (auth.role() = 'authenticated')","-- Allow admins to mutate\nCREATE POLICY \\"Allow admin all company_profile\\" ON public.company_profile FOR ALL USING (auth.role() = 'authenticated')","CREATE POLICY \\"Allow admin all hsn_master\\" ON public.hsn_master FOR ALL USING (auth.role() = 'authenticated')","CREATE POLICY \\"Allow admin all invoice_sequences\\" ON public.invoice_sequences FOR ALL USING (auth.role() = 'authenticated')"}	phase1_hsn_master_architecture
20260621235000	{"-- Create products table in Supabase (Migrating from Firebase)\nCREATE TABLE IF NOT EXISTS public.products (\n  id                  TEXT PRIMARY KEY,  -- Using TEXT since Firebase IDs are strings like \\"6000\\"\n  name                TEXT NOT NULL,\n  name_lowercase      TEXT,\n  category            TEXT NOT NULL,\n  printer_category    TEXT,\n  status              TEXT DEFAULT 'ACTIVE',\n  base_rate           NUMERIC(10,2) NOT NULL,\n  eyelet_metal        NUMERIC(10,2) DEFAULT 0,\n  eyelet_plastic      NUMERIC(10,2) DEFAULT 0,\n  delivery_door       NUMERIC(10,2) DEFAULT 0,\n  delivery_courier    NUMERIC(10,2) DEFAULT 0,\n  delivery_transport  NUMERIC(10,2) DEFAULT 0,\n  media_images        JSONB DEFAULT '[]',\n  media_video_url     TEXT,\n  specs_max_width     TEXT,\n  specs_gsm           TEXT,\n  specs_description   TEXT,\n  workflow_steps      JSONB DEFAULT '[]',\n\n  -- New HSN Fields\n  hsn_master_id       UUID REFERENCES public.hsn_master(id),\n  hsn_code            VARCHAR(8),\n  hsn_description     TEXT,\n  gst_rate            NUMERIC(5,2),\n  gst_effective_from  DATE,\n  product_snapshot_version INTEGER DEFAULT 1,\n\n  created_at          TIMESTAMPTZ DEFAULT now(),\n  updated_at          TIMESTAMPTZ DEFAULT now()\n)","-- 2. Create product audit logs\nCREATE TABLE IF NOT EXISTS public.product_audit_logs (\n  id              UUID         PRIMARY KEY DEFAULT gen_random_uuid(),\n  product_id      TEXT         NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,\n  old_hsn_code    VARCHAR(8),\n  new_hsn_code    VARCHAR(8),\n  old_gst_rate    NUMERIC(5,2),\n  new_gst_rate    NUMERIC(5,2),\n  updated_by      TEXT,\n  reason          TEXT,\n  created_at      TIMESTAMPTZ  DEFAULT now()\n)","-- Index for querying audits by product\nCREATE INDEX idx_product_audit_logs_product_id ON public.product_audit_logs(product_id)"}	phase2_product_hsn
20260622000000	{"-- Alter products table to add HSN fields\nALTER TABLE public.products\n  ADD COLUMN IF NOT EXISTS hsn_master_id UUID REFERENCES public.hsn_master(id),\n  ADD COLUMN IF NOT EXISTS hsn_code VARCHAR(8),\n  ADD COLUMN IF NOT EXISTS hsn_description TEXT,\n  ADD COLUMN IF NOT EXISTS gst_rate NUMERIC(5,2),\n  ADD COLUMN IF NOT EXISTS gst_effective_from DATE,\n  ADD COLUMN IF NOT EXISTS product_snapshot_version INTEGER DEFAULT 1"}	phase2_product_hsn_alter
20260622010000	{"-- Phase 4: Enterprise Invoice Schema Upgrade\n\n-- Drop the old table completely, we are redesigning from scratch.\nDROP TABLE IF EXISTS public.invoice_generation_attempts CASCADE","DROP TABLE IF EXISTS public.invoice_events CASCADE","DROP TABLE IF EXISTS public.invoices CASCADE","DROP TYPE IF EXISTS invoice_event_type CASCADE","-- 1. Create generalized enum for invoice events\nCREATE TYPE invoice_event_type AS ENUM (\n  'PENDING_CREATED', 'GENERATION_STARTED', 'GENERATION_COMPLETED', 'GENERATION_FAILED', 'GENERATION_RETRIED',\n  'PDF_GENERATED', 'PDF_DOWNLOADED', 'EMAIL_SENT',\n  'WHATSAPP_SENT', 'DISPATCH_UPDATED', 'DISPATCH_ROLLED_BACK', 'CANCELLED', 'CREDIT_NOTE_CREATED',\n  'SYSTEM_RESTART', 'WORKER_TIMEOUT', 'MANUAL_RETRY'\n)","-- 2. Invoices (Complete Redesign)\nCREATE TABLE public.invoices (\n  -- Identity\n  id                            TEXT         PRIMARY KEY,\n  invoice_number                TEXT         UNIQUE NOT NULL,       -- IMMUTABLE: HE/2026-27/0148\n  invoice_sequence              INTEGER      NOT NULL,              -- 148\n  financial_year                TEXT         NOT NULL REFERENCES public.invoice_sequences(financial_year),\n  invoice_number_reserved_at    TIMESTAMPTZ  NOT NULL,              \n  reservation_reason            TEXT,                               \n  reservation_user_id           TEXT,                               \n  reservation_user_name         TEXT,                               \n  invoice_schema_version        INTEGER      NOT NULL DEFAULT 1,\n  parent_order_id               TEXT         NOT NULL,\n\n  -- Status machine\n  status                        TEXT         NOT NULL DEFAULT 'PENDING',\n\n  -- Queue metrics (top level)\n  generation_requested_at  TIMESTAMPTZ,\n  queued_at                TIMESTAMPTZ,\n  started_at               TIMESTAMPTZ,\n  finished_at              TIMESTAMPTZ,\n  processing_time_ms       INTEGER,\n  queue_name               TEXT,\n  worker_id                TEXT,\n  generation_lock_until    TIMESTAMPTZ,                              -- Soft lock: another worker can claim if this timestamp is passed\n\n  -- Retry tracking\n  attempt_count            INTEGER      DEFAULT 0,\n  max_attempts             INTEGER      DEFAULT 6,\n  last_error               TEXT,\n  last_attempted_at        TIMESTAMPTZ,\n  current_attempt_id       TEXT,\n  generating_heartbeat_at  TIMESTAMPTZ,\n\n  -- Security & Audit\n  financial_lock_at        TIMESTAMPTZ,                              -- When financial fields became permanently frozen\n  snapshot_hash            TEXT,                                     -- SHA-256 covering Customer, Company, Items, Tax, Totals, Invoice No, Date, FY, and Schema Version\n  snapshot_hash_algorithm  TEXT         DEFAULT 'SHA-256',\n\n  -- Customer snapshot (immutable after GENERATED)\n  customer_id              TEXT         NOT NULL,\n  customer_snapshot        JSONB        NOT NULL DEFAULT '{}',\n\n  -- Company snapshot (immutable after GENERATED)\n  company_snapshot         JSONB        NOT NULL DEFAULT '{}',\n\n  -- Items snapshot (immutable after GENERATED)\n  items                    JSONB        NOT NULL DEFAULT '[]',\n\n  -- Tax snapshot (immutable after GENERATED — all NUMERIC)\n  is_inter_state           BOOLEAN,\n  taxable_value            NUMERIC(12,2),\n  cgst_rate                NUMERIC(5,2),\n  cgst_amount              NUMERIC(12,2),\n  sgst_rate                NUMERIC(5,2),\n  sgst_amount              NUMERIC(12,2),\n  igst_rate                NUMERIC(5,2),\n  igst_amount              NUMERIC(12,2),\n  round_off                NUMERIC(10,2),\n  grand_total              NUMERIC(12,2),\n  amount_in_words          TEXT,\n\n  -- PDF storage\n  pdf_url                  TEXT,\n  pdf_generated_at         TIMESTAMPTZ,\n  pdf_version              INTEGER      DEFAULT 0,\n  pdf_template_version     TEXT,\n  pdf_sha256               TEXT,                                     -- SHA-256 of the generated PDF buffer\n  pdf_size_bytes           INTEGER,\n  pdf_content_type         TEXT,\n  pdf_generated_by         TEXT,                                     -- e.g. 'ERP 1.0.0'\n\n  -- System provenance\n  generated_by_system_version TEXT,\n  generation_version       INTEGER      DEFAULT 1,                   -- E.g. algorithm version 1, 2, 3\n\n  -- Future e-invoice fields (reserved, always NULL for now)\n  irn                      TEXT,\n  ack_number               TEXT,\n  ack_date                 TIMESTAMPTZ,\n  qr_code                  TEXT,\n  signed_invoice           TEXT,\n\n  -- Invoice metadata\n  invoice_type             TEXT         DEFAULT 'ORIGINAL',\n  amendment_of             TEXT         REFERENCES public.invoices(id),\n  invoice_date             DATE         NOT NULL,\n  order_type               TEXT,\n  payment_status           TEXT,\n\n  -- Current dispatch summary (mutable — every change logged to invoice_events)\n  lr_number                TEXT,\n  transporter              TEXT,\n  vehicle_number           TEXT,\n  eway_bill                TEXT,\n  dispatch_date            DATE,\n  delivery_date            DATE,\n  remarks                  TEXT,\n  row_version              INTEGER      DEFAULT 1,                   -- Optimistic locking for admin edits\n\n  -- Timestamps\n  created_at               TIMESTAMPTZ  DEFAULT now(),\n  generated_at             TIMESTAMPTZ,\n  cancelled_at             TIMESTAMPTZ,\n\n  CONSTRAINT valid_invoice_status CHECK (\n    status IN (\n      'PENDING', 'GENERATING', 'GENERATED',\n      'FAILED', 'PERMANENTLY_FAILED', 'DLQ',\n      'DISPATCH_ROLLED_BACK', 'CANCELLED'\n    )\n  ),\n  CONSTRAINT valid_invoice_type CHECK (\n    invoice_type IN ('ORIGINAL', 'CREDIT_NOTE', 'DEBIT_NOTE')\n  )\n)","-- Allowed multiple invoices per order to support PARTIAL DISPATCH in the future\nCREATE INDEX idx_invoices_parent_order ON public.invoices (parent_order_id)","CREATE INDEX idx_invoices_status ON public.invoices (status)","-- Dashboard Query Indexes\nCREATE INDEX idx_invoices_invoice_date ON public.invoices (invoice_date)","CREATE INDEX idx_invoices_financial_year ON public.invoices (financial_year)","CREATE INDEX idx_invoices_generated_at ON public.invoices (generated_at)","CREATE INDEX idx_invoices_customer_id ON public.invoices (customer_id)","CREATE INDEX idx_invoices_invoice_number ON public.invoices (invoice_number)","-- Enable RLS\nALTER TABLE public.invoices ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"Allow authenticated full access to invoices\\" ON public.invoices FOR ALL USING (auth.role() = 'authenticated')","-- 3. Invoice Events (Generalized Audit Log)\nCREATE TABLE public.invoice_events (\n  id              UUID         PRIMARY KEY DEFAULT gen_random_uuid(),\n  invoice_id      TEXT         NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,\n  event_type      invoice_event_type NOT NULL, \n  field_name      TEXT,        -- optional, if it's a specific field change\n  old_value       TEXT,\n  new_value       TEXT,\n  event_metadata  JSONB,       -- for structured data like error traces\n  actor_id        TEXT,\n  actor_name      TEXT,\n  created_at      TIMESTAMPTZ  DEFAULT now()\n)","CREATE INDEX idx_invoice_events_invoice ON public.invoice_events (invoice_id)","CREATE INDEX idx_invoice_events_type ON public.invoice_events (event_type)","ALTER TABLE public.invoice_events ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"Allow authenticated full access to invoice_events\\" ON public.invoice_events FOR ALL USING (auth.role() = 'authenticated')","-- 4. Invoice Generation Attempts (Background job history)\nCREATE TABLE public.invoice_generation_attempts (\n  id              UUID         PRIMARY KEY DEFAULT gen_random_uuid(),\n  invoice_id      TEXT         NOT NULL REFERENCES public.invoices(id) ON DELETE CASCADE,\n  attempt_number  INTEGER      NOT NULL,\n  queue_name      TEXT,\n  worker_id       TEXT,\n  started_at      TIMESTAMPTZ,\n  finished_at     TIMESTAMPTZ,\n  result_status   TEXT,        -- SUCCESS, FAILED\n  error_message   TEXT,\n  error_trace     TEXT\n)","CREATE INDEX idx_invoice_attempts_invoice ON public.invoice_generation_attempts (invoice_id)","ALTER TABLE public.invoice_generation_attempts ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"Allow authenticated full access to invoice_generation_attempts\\" ON public.invoice_generation_attempts FOR ALL USING (auth.role() = 'authenticated')"}	phase4_enterprise_invoices
20260622020000	{"-- Phase 5: RPC for atomic invoice generation\n\nCREATE OR REPLACE FUNCTION public.get_financial_year(p_date DATE) RETURNS TEXT AS $$\nDECLARE\n  v_year INTEGER := extract(year from p_date);\n  v_month INTEGER := extract(month from p_date);\n  v_next_year INTEGER;\nBEGIN\n  IF v_month < 4 THEN\n    v_next_year := v_year;\n    v_year := v_year - 1;\n  ELSE\n    v_next_year := v_year + 1;\n  END IF;\n  RETURN v_year::TEXT || '-' || right(v_next_year::TEXT, 2);\nEND;\n$$ LANGUAGE plpgsql IMMUTABLE","CREATE OR REPLACE FUNCTION public.reserve_invoice_number(p_invoice_date DATE)\nRETURNS TABLE (\n  invoice_number TEXT,\n  invoice_sequence INTEGER,\n  financial_year TEXT\n) AS $$\nDECLARE\n  v_fy TEXT;\n  v_prefix TEXT;\n  v_separator TEXT;\n  v_padding INTEGER;\n  v_seq INTEGER;\n  v_is_locked BOOLEAN;\n  v_inv_num TEXT;\nBEGIN\n  v_fy := public.get_financial_year(p_invoice_date);\n\n  -- Lock the row for update\n  SELECT prefix, separator, padding_length, last_number, is_locked \n  INTO v_prefix, v_separator, v_padding, v_seq, v_is_locked\n  FROM public.invoice_sequences\n  WHERE financial_year = v_fy\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    -- Auto-create sequence for new FY if it doesn't exist\n    INSERT INTO public.invoice_sequences (financial_year, prefix, separator, padding_length, last_number)\n    VALUES (v_fy, 'HE', '/', 6, 0)\n    RETURNING prefix, separator, padding_length, last_number, is_locked\n    INTO v_prefix, v_separator, v_padding, v_seq, v_is_locked;\n  END IF;\n\n  IF v_is_locked THEN\n    RAISE EXCEPTION 'Financial year % is locked. Cannot generate invoices.', v_fy;\n  END IF;\n\n  v_seq := v_seq + 1;\n\n  UPDATE public.invoice_sequences\n  SET last_number = v_seq, updated_at = now()\n  WHERE financial_year = v_fy;\n\n  v_inv_num := v_prefix || v_separator || v_fy || v_separator || lpad(v_seq::TEXT, v_padding, '0');\n\n  RETURN QUERY SELECT v_inv_num, v_seq, v_fy;\nEND;\n$$ LANGUAGE plpgsql","-- Also we need an RPC to insert the invoice atomically if we don't want to do multiple roundtrips,\n-- but since we just need the number, returning the number is fine. We can just insert it from TS."}	phase5_invoice_rpc
20260622030000	{"-- Phase 5: RPC for atomic invoice generation\r\n\r\nCREATE OR REPLACE FUNCTION public.get_financial_year(p_date DATE) RETURNS TEXT AS $$\r\nDECLARE\r\n  v_year INTEGER := extract(year from p_date);\r\n  v_month INTEGER := extract(month from p_date);\r\n  v_next_year INTEGER;\r\nBEGIN\r\n  IF v_month < 4 THEN\r\n    v_next_year := v_year;\r\n    v_year := v_year - 1;\r\n  ELSE\r\n    v_next_year := v_year + 1;\r\n  END IF;\r\n  RETURN v_year::TEXT || '-' || right(v_next_year::TEXT, 2);\r\nEND;\r\n$$ LANGUAGE plpgsql IMMUTABLE","CREATE OR REPLACE FUNCTION public.reserve_invoice_number(p_invoice_date DATE)\r\nRETURNS TABLE (\r\n  invoice_number TEXT,\r\n  invoice_sequence INTEGER,\r\n  financial_year TEXT\r\n) AS $$\r\nDECLARE\r\n  v_fy TEXT;\r\n  v_prefix TEXT;\r\n  v_separator TEXT;\r\n  v_padding INTEGER;\r\n  v_seq INTEGER;\r\n  v_is_locked BOOLEAN;\r\n  v_inv_num TEXT;\r\nBEGIN\r\n  v_fy := public.get_financial_year(p_invoice_date);\r\n\r\n  -- Lock the row for update\r\n  SELECT prefix, last_number, is_locked \r\n  INTO v_prefix, v_seq, v_is_locked\r\n  FROM public.invoice_sequences\r\n  WHERE financial_year = v_fy\r\n  FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    -- Auto-create sequence for new FY if it doesn't exist\r\n    INSERT INTO public.invoice_sequences (financial_year, prefix, separator, padding_length, last_number)\r\n    VALUES (v_fy, 'HE/', 0)\r\n    RETURNING prefix, last_number, is_locked\r\n    INTO v_prefix, v_seq, v_is_locked;\r\n  END IF;\r\n\r\n  IF v_is_locked THEN\r\n    RAISE EXCEPTION 'Financial year % is locked. Cannot generate invoices.', v_fy;\r\n  END IF;\r\n\r\n  v_seq := v_seq + 1;\r\n\r\n  UPDATE public.invoice_sequences\r\n  SET last_number = v_seq, updated_at = now()\r\n  WHERE financial_year = v_fy;\r\n\r\n  v_inv_num := v_prefix || v_fy || '/' || lpad(v_seq::TEXT, 6, '0');\r\n\r\n  RETURN QUERY SELECT v_inv_num, v_seq, v_fy;\r\nEND;\r\n$$ LANGUAGE plpgsql","-- Also we need an RPC to insert the invoice atomically if we don't want to do multiple roundtrips,\r\n-- but since we just need the number, returning the number is fine. We can just insert it from TS."}	phase5_invoice_rpc_fix
20260622050000	{"-- Migration: Atomic Dispatch RPC\n\nCREATE OR REPLACE FUNCTION public.atomic_dispatch_order(\n  p_order_id TEXT,\n  p_actor_id TEXT,\n  p_actor_name TEXT,\n  p_invoice_date DATE\n)\nRETURNS TABLE (\n  success BOOLEAN,\n  invoice_id TEXT,\n  invoice_number TEXT,\n  message TEXT\n) AS $$\nDECLARE\n  v_current_status TEXT;\n  v_customer_id TEXT;\n  v_inv_id TEXT;\n  v_inv_status TEXT;\n  v_inv_number TEXT;\n  v_fy TEXT;\n  v_prefix TEXT;\n  v_seq INTEGER;\n  v_is_locked BOOLEAN;\n  v_new_inv_num TEXT;\n  v_new_inv_id TEXT;\nBEGIN\n  -- 1. Lock and validate order\n  SELECT status, \\"customerId\\"\n  INTO v_current_status, v_customer_id\n  FROM public.orders\n  WHERE id = p_order_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, NULL::TEXT, NULL::TEXT, 'Order not found'::TEXT;\n    RETURN;\n  END IF;\n\n  -- 2. Verify not already dispatched\n  IF v_current_status = 'DISPATCHED' THEN\n    -- Find existing invoice if any\n    SELECT id, public.invoices.invoice_number INTO v_inv_id, v_inv_number\n    FROM public.invoices WHERE parent_order_id = p_order_id LIMIT 1;\n    \n    RETURN QUERY SELECT true, v_inv_id, v_inv_number, 'Order already dispatched'::TEXT;\n    RETURN;\n  END IF;\n\n  -- 3. Update order status\n  UPDATE public.orders\n  SET status = 'DISPATCHED', updated_at = now()\n  WHERE id = p_order_id;\n\n  -- 4. Check existing invoice row\n  SELECT id, status, public.invoices.invoice_number \n  INTO v_inv_id, v_inv_status, v_inv_number\n  FROM public.invoices \n  WHERE parent_order_id = p_order_id \n  LIMIT 1;\n\n  IF FOUND THEN\n    -- Business rules for existing invoice\n    IF v_inv_status = 'DISPATCH_ROLLED_BACK' THEN\n      UPDATE public.invoices\n      SET status = 'PENDING', updated_at = now()\n      WHERE id = v_inv_id;\n\n      INSERT INTO public.invoice_events (invoice_id, event_type, actor_id, actor_name)\n      VALUES (v_inv_id, 'PENDING_CREATED', p_actor_id, p_actor_name);\n      \n      RETURN QUERY SELECT true, v_inv_id, v_inv_number, 'Reused rolled back invoice'::TEXT;\n      RETURN;\n    ELSE\n      -- PENDING, GENERATING, GENERATED, FAILED, PERMANENTLY_FAILED, DLQ\n      RETURN QUERY SELECT true, v_inv_id, v_inv_number, 'Invoice already exists in status ' || v_inv_status;\n      RETURN;\n    END IF;\n  END IF;\n\n  -- 5. Reserve new invoice number\n  v_fy := public.get_financial_year(p_invoice_date);\n\n  SELECT prefix, last_number, is_locked \n  INTO v_prefix, v_seq, v_is_locked\n  FROM public.invoice_sequences\n  WHERE public.invoice_sequences.financial_year = v_fy\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    INSERT INTO public.invoice_sequences (financial_year, prefix, separator, padding_length, last_number)\n    VALUES (v_fy, 'HE/', '/', 6, 0)\n    RETURNING prefix, last_number, is_locked\n    INTO v_prefix, v_seq, v_is_locked;\n  END IF;\n\n  IF v_is_locked THEN\n    RAISE EXCEPTION 'Financial year % is locked. Cannot generate invoices.', v_fy;\n  END IF;\n\n  v_seq := v_seq + 1;\n\n  UPDATE public.invoice_sequences\n  SET last_number = v_seq, updated_at = now()\n  WHERE public.invoice_sequences.financial_year = v_fy;\n\n  v_new_inv_num := v_prefix || v_fy || '/' || lpad(v_seq::TEXT, 6, '0');\n  v_new_inv_id := 'INV-' || gen_random_uuid()::TEXT;\n\n  -- 6. Create Invoice Row (PENDING)\n  INSERT INTO public.invoices (\n    id, invoice_number, invoice_sequence, financial_year,\n    invoice_number_reserved_at, parent_order_id, status,\n    customer_id, invoice_date, reservation_user_id, reservation_user_name\n  ) VALUES (\n    v_new_inv_id, v_new_inv_num, v_seq, v_fy,\n    now(), p_order_id, 'PENDING',\n    v_customer_id, p_invoice_date, p_actor_id, p_actor_name\n  );\n\n  -- 7. Insert Initial Event\n  INSERT INTO public.invoice_events (invoice_id, event_type, actor_id, actor_name)\n  VALUES (v_new_inv_id, 'PENDING_CREATED', p_actor_id, p_actor_name);\n\n  RETURN QUERY SELECT true, v_new_inv_id, v_new_inv_num, 'Successfully dispatched and reserved invoice'::TEXT;\nEND;\n$$ LANGUAGE plpgsql"}	phase6_atomic_dispatch
20260622060000	{"-- Add integrity status columns to invoices\nALTER TABLE invoices\nADD COLUMN IF NOT EXISTS invoice_integrity_status VARCHAR NOT NULL DEFAULT 'NOT_VERIFIED',\nADD COLUMN IF NOT EXISTS last_verified_at TIMESTAMPTZ,\nADD COLUMN IF NOT EXISTS last_verified_by VARCHAR,\nADD COLUMN IF NOT EXISTS last_verification_hash VARCHAR","-- Create audit history table for integrity checks\nCREATE TABLE IF NOT EXISTS invoice_integrity_checks (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    invoice_id VARCHAR NOT NULL REFERENCES invoices(id),\n    verified_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n    verified_by VARCHAR NOT NULL DEFAULT 'SYSTEM',\n    expected_snapshot_hash VARCHAR,\n    calculated_snapshot_hash VARCHAR,\n    snapshot_result VARCHAR NOT NULL,\n    expected_pdf_hash VARCHAR,\n    calculated_pdf_hash VARCHAR,\n    pdf_result VARCHAR NOT NULL,\n    final_result VARCHAR NOT NULL,\n    verification_duration_ms INTEGER,\n    algorithm VARCHAR NOT NULL DEFAULT 'SHA-256'\n)","-- Index for querying audit history by invoice\nCREATE INDEX IF NOT EXISTS idx_invoice_integrity_checks_invoice_id ON invoice_integrity_checks(invoice_id)"}	phase7_invoice_integrity
20260622070000	{"-- Trigger to strictly enforce financial immutability after the financial lock is set\nCREATE OR REPLACE FUNCTION enforce_invoice_immutability()\nRETURNS TRIGGER AS $$\nBEGIN\n  -- We only enforce this if the old row has financial_lock_at set\n  IF OLD.financial_lock_at IS NOT NULL THEN\n    -- Check if any protected column is being modified\n    IF OLD.customer_snapshot IS DISTINCT FROM NEW.customer_snapshot OR\n       OLD.company_snapshot IS DISTINCT FROM NEW.company_snapshot OR\n       OLD.items IS DISTINCT FROM NEW.items OR\n       OLD.taxable_value IS DISTINCT FROM NEW.taxable_value OR\n       OLD.cgst_amount IS DISTINCT FROM NEW.cgst_amount OR\n       OLD.sgst_amount IS DISTINCT FROM NEW.sgst_amount OR\n       OLD.igst_amount IS DISTINCT FROM NEW.igst_amount OR\n       OLD.grand_total IS DISTINCT FROM NEW.grand_total OR\n       OLD.invoice_number IS DISTINCT FROM NEW.invoice_number OR\n       OLD.invoice_date IS DISTINCT FROM NEW.invoice_date OR\n       OLD.financial_year IS DISTINCT FROM NEW.financial_year OR\n       OLD.snapshot_hash IS DISTINCT FROM NEW.snapshot_hash OR\n       OLD.pdf_sha256 IS DISTINCT FROM NEW.pdf_sha256 OR\n       OLD.pdf_url IS DISTINCT FROM NEW.pdf_url OR\n       OLD.pdf_generated_at IS DISTINCT FROM NEW.pdf_generated_at\n    THEN\n      RAISE EXCEPTION 'Invoice is financially locked. Modification of immutable financial or snapshot fields is strictly prohibited.';\n    END IF;\n  END IF;\n\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql","-- Apply the trigger to the invoices table\nDROP TRIGGER IF EXISTS trigger_enforce_invoice_immutability ON invoices","CREATE TRIGGER trigger_enforce_invoice_immutability\nBEFORE UPDATE ON invoices\nFOR EACH ROW\nEXECUTE FUNCTION enforce_invoice_immutability()"}	phase7_immutability_trigger
20260622080000	{"-- Ensure all product columns exist (in case previous migrations were applied before these columns were added to the schema locally)\n\nDO $$ \nBEGIN\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN base_rate NUMERIC(10,2) NOT NULL DEFAULT 0;\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN eyelet_metal NUMERIC(10,2) DEFAULT 0;\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN eyelet_plastic NUMERIC(10,2) DEFAULT 0;\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN delivery_door NUMERIC(10,2) DEFAULT 0;\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN delivery_courier NUMERIC(10,2) DEFAULT 0;\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN delivery_transport NUMERIC(10,2) DEFAULT 0;\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN media_images JSONB DEFAULT '[]';\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN media_video_url TEXT;\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN specs_max_width TEXT;\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN specs_gsm TEXT;\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN specs_description TEXT;\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN workflow_steps JSONB DEFAULT '[]';\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  -- HSN Fields\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN hsn_master_id UUID REFERENCES public.hsn_master(id);\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN hsn_code VARCHAR(8);\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN hsn_description TEXT;\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN gst_rate NUMERIC(5,2);\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN gst_effective_from DATE;\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\n\n  BEGIN\n    ALTER TABLE public.products ADD COLUMN product_snapshot_version INTEGER DEFAULT 1;\n  EXCEPTION\n    WHEN duplicate_column THEN null;\n  END;\nEND $$","-- Force schema reload for PostgREST\nNOTIFY pgrst, 'reload schema'"}	phase8_add_missing_product_columns
20260622090000	{"-- Add name_lowercase column to products table if it doesn't exist\nALTER TABLE public.products ADD COLUMN IF NOT EXISTS name_lowercase TEXT","-- Update existing records to have name_lowercase populated\nUPDATE public.products SET name_lowercase = LOWER(name) WHERE name_lowercase IS NULL","-- Reload postgREST schema cache\nNOTIFY pgrst, 'reload schema'"}	add_name_lowercase_to_products
20260623000000	{"-- ============================================================\n-- New Invoice Architecture Migration\n-- Replaces automatic-dispatch invoice generation with\n-- manual Invoice Generation module.\n-- ============================================================\n\n-- 1. Add immutable financial snapshot columns to the orders table\n--    These are set once at child order creation and never modified.\n--    NULL = order created before this migration (handled gracefully by UI).\n\nALTER TABLE public.orders\n  ADD COLUMN IF NOT EXISTS cgst_percentage         NUMERIC(5,2),\n  ADD COLUMN IF NOT EXISTS cgst_amount             NUMERIC(12,2),\n  ADD COLUMN IF NOT EXISTS sgst_percentage         NUMERIC(5,2),\n  ADD COLUMN IF NOT EXISTS sgst_amount             NUMERIC(12,2),\n  ADD COLUMN IF NOT EXISTS igst_percentage         NUMERIC(5,2),\n  ADD COLUMN IF NOT EXISTS igst_amount             NUMERIC(12,2),\n  ADD COLUMN IF NOT EXISTS gst_type                TEXT,          -- 'CGST_SGST' | 'IGST'\n  ADD COLUMN IF NOT EXISTS allocated_logistics_percentage NUMERIC(8,4),\n  ADD COLUMN IF NOT EXISTS allocated_logistics_amount     NUMERIC(12,2),\n  ADD COLUMN IF NOT EXISTS item_amount             NUMERIC(12,2),\n  ADD COLUMN IF NOT EXISTS taxable_value_snapshot  NUMERIC(12,2),\n  ADD COLUMN IF NOT EXISTS grand_total_snapshot    NUMERIC(12,2),\n  -- Invoice link fields (set when invoice is generated for this child order)\n  ADD COLUMN IF NOT EXISTS invoice_id              TEXT,\n  ADD COLUMN IF NOT EXISTS invoice_number          TEXT,\n  ADD COLUMN IF NOT EXISTS invoice_generated       BOOLEAN NOT NULL DEFAULT FALSE,\n  ADD COLUMN IF NOT EXISTS invoice_generated_at    TIMESTAMPTZ,\n  ADD COLUMN IF NOT EXISTS invoice_status          TEXT DEFAULT 'PENDING'","-- PENDING | GENERATED | PRINTED | HANDED_OVER | CANCELLED\n\n-- Index for fast lookups in Invoice Generation module\nCREATE INDEX IF NOT EXISTS idx_orders_invoice_generated ON public.orders (invoice_generated)","CREATE INDEX IF NOT EXISTS idx_orders_invoice_id ON public.orders (invoice_id)","CREATE INDEX IF NOT EXISTS idx_orders_customer_id_status ON public.orders (\\"customerId\\", status)","-- 2. Revamp atomic_dispatch_order RPC\n--    Remove invoice number reservation entirely.\n--    Dispatch now only marks the order DISPATCHED — nothing more.\n\nCREATE OR REPLACE FUNCTION public.atomic_dispatch_order(\n  p_order_id TEXT,\n  p_actor_id TEXT,\n  p_actor_name TEXT,\n  p_invoice_date DATE DEFAULT CURRENT_DATE\n)\nRETURNS TABLE (\n  success BOOLEAN,\n  invoice_id TEXT,\n  invoice_number TEXT,\n  message TEXT\n) AS $$\nDECLARE\n  v_current_status TEXT;\nBEGIN\n  -- 1. Lock and validate the order\n  SELECT status\n  INTO v_current_status\n  FROM public.orders\n  WHERE id = p_order_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RETURN QUERY SELECT false, NULL::TEXT, NULL::TEXT, 'Order not found'::TEXT;\n    RETURN;\n  END IF;\n\n  -- 2. Idempotency: already dispatched is fine\n  IF v_current_status = 'DISPATCHED' THEN\n    RETURN QUERY SELECT true, NULL::TEXT, NULL::TEXT, 'Order already dispatched'::TEXT;\n    RETURN;\n  END IF;\n\n  -- 3. Mark as dispatched — no invoice number reserved here\n  UPDATE public.orders\n  SET status = 'DISPATCHED', updated_at = now()\n  WHERE id = p_order_id;\n\n  RETURN QUERY SELECT true, NULL::TEXT, NULL::TEXT, 'Successfully dispatched'::TEXT;\nEND;\n$$ LANGUAGE plpgsql","-- 3. New atomic invoice generation RPC\n--    Called by the Invoice Generation module when staff clicks \\"Generate Invoice\\".\n--    Assigns the next sequential invoice number and atomically links it to\n--    the selected child orders.\n\nCREATE OR REPLACE FUNCTION public.generate_invoice_for_child_orders(\n  p_child_order_ids   TEXT[],\n  p_parent_order_id   TEXT,\n  p_customer_id       TEXT,\n  p_actor_id          TEXT,\n  p_actor_name        TEXT,\n  p_invoice_date      DATE DEFAULT CURRENT_DATE\n)\nRETURNS TABLE (\n  success          BOOLEAN,\n  invoice_id       TEXT,\n  invoice_number   TEXT,\n  message          TEXT\n) AS $$\nDECLARE\n  v_fy             TEXT;\n  v_prefix         TEXT;\n  v_seq            INTEGER;\n  v_is_locked      BOOLEAN;\n  v_new_inv_num    TEXT;\n  v_new_inv_id     TEXT;\n  v_already_invoiced INTEGER;\n  v_order_id       TEXT;\nBEGIN\n  -- 1. Validate that none of the selected child orders are already invoiced\n  SELECT COUNT(*)\n  INTO v_already_invoiced\n  FROM public.orders\n  WHERE id = ANY(p_child_order_ids)\n    AND invoice_generated = TRUE;\n\n  IF v_already_invoiced > 0 THEN\n    RETURN QUERY SELECT false, NULL::TEXT, NULL::TEXT,\n      format('%s selected item(s) are already invoiced. Deselect them and try again.', v_already_invoiced)::TEXT;\n    RETURN;\n  END IF;\n\n  -- 2. Lock all selected child orders for update (prevents concurrent generation)\n  PERFORM id FROM public.orders\n  WHERE id = ANY(p_child_order_ids)\n  FOR UPDATE;\n\n  -- 3. Reserve the next sequential invoice number\n  v_fy := public.get_financial_year(p_invoice_date);\n\n  SELECT prefix, last_number, is_locked\n  INTO v_prefix, v_seq, v_is_locked\n  FROM public.invoice_sequences\n  WHERE financial_year = v_fy\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    INSERT INTO public.invoice_sequences (financial_year, prefix, separator, padding_length, last_number)\n    VALUES (v_fy, 'HE/', '/', 6, 0)\n    RETURNING prefix, last_number, is_locked\n    INTO v_prefix, v_seq, v_is_locked;\n  END IF;\n\n  IF v_is_locked THEN\n    RAISE EXCEPTION 'Financial year % is locked. Cannot generate invoices.', v_fy;\n  END IF;\n\n  v_seq := v_seq + 1;\n\n  UPDATE public.invoice_sequences\n  SET last_number = v_seq, updated_at = now()\n  WHERE financial_year = v_fy;\n\n  v_new_inv_num := v_prefix || v_fy || '/' || lpad(v_seq::TEXT, 6, '0');\n  v_new_inv_id  := 'INV-' || gen_random_uuid()::TEXT;\n\n  -- 4. Create the invoice row\n  INSERT INTO public.invoices (\n    id, invoice_number, invoice_sequence, financial_year,\n    invoice_number_reserved_at, parent_order_id, status,\n    customer_id, invoice_date, reservation_user_id, reservation_user_name,\n    generated_at\n  ) VALUES (\n    v_new_inv_id, v_new_inv_num, v_seq, v_fy,\n    now(), p_parent_order_id, 'GENERATED',\n    p_customer_id, p_invoice_date, p_actor_id, p_actor_name,\n    now()\n  );\n\n  -- 5. Log the generation event\n  INSERT INTO public.invoice_events (invoice_id, event_type, actor_id, actor_name, event_metadata)\n  VALUES (v_new_inv_id, 'GENERATION_COMPLETED', p_actor_id, p_actor_name,\n          jsonb_build_object('child_order_ids', to_jsonb(p_child_order_ids)));\n\n  -- 6. Stamp each selected child order with the invoice reference\n  UPDATE public.orders\n  SET\n    invoice_id           = v_new_inv_id,\n    invoice_number       = v_new_inv_num,\n    invoice_generated    = TRUE,\n    invoice_generated_at = now(),\n    invoice_status       = 'GENERATED',\n    updated_at           = now()\n  WHERE id = ANY(p_child_order_ids);\n\n  RETURN QUERY SELECT true, v_new_inv_id, v_new_inv_num, 'Invoice generated successfully'::TEXT;\nEND;\n$$ LANGUAGE plpgsql","-- 4. Add transport_amount column to invoices if missing (for summary storage)\nALTER TABLE public.invoices\n  ADD COLUMN IF NOT EXISTS transport_amount NUMERIC(12,2) DEFAULT 0,\n  ADD COLUMN IF NOT EXISTS child_order_ids  TEXT[]        DEFAULT '{}',\n  ADD COLUMN IF NOT EXISTS item_count       INTEGER       DEFAULT 0","-- Index for querying invoices by parent order quickly\nCREATE INDEX IF NOT EXISTS idx_invoices_parent_order_new ON public.invoices (parent_order_id)"}	new_invoice_architecture
20260623010000	{"-- SQL Migration: Update place_order_tx to include new financial snapshot columns\n-- Adds cgst_percentage, cgst_amount, sgst_percentage, sgst_amount, igst_percentage, igst_amount, \n-- gst_type, allocated_logistics_percentage, allocated_logistics_amount, item_amount, \n-- taxable_value_snapshot, grand_total_snapshot\n\nCREATE OR REPLACE FUNCTION place_order_tx(\n  p_customer_id text,\n  p_order_type text,\n  p_grand_total numeric,\n  p_parent_order jsonb,\n  p_child_orders jsonb[],\n  p_order_items jsonb[],\n  p_ledger_entries jsonb[],\n  p_jobs jsonb[],\n  p_idempotency_key text\n) RETURNS jsonb LANGUAGE plpgsql AS $$\nDECLARE\n  v_used_credit numeric;\n  v_credit_limit numeric;\n  v_new_used_credit numeric;\n  v_result jsonb;\n  v_exists boolean;\n  v_now timestamp with time zone := NOW();\n  v_now_json jsonb := to_jsonb(v_now::text);\nBEGIN\n  -- 1. Idempotency Check\n  IF p_idempotency_key IS NOT NULL THEN\n    SELECT EXISTS(SELECT 1 FROM idempotency_keys WHERE idempotency_key = p_idempotency_key) INTO v_exists;\n    IF v_exists THEN\n      -- Retrieve the existing order ID corresponding to this idempotency key\n      SELECT order_id INTO v_result FROM idempotency_keys WHERE idempotency_key = p_idempotency_key;\n      RETURN jsonb_build_object(\n        'success', true,\n        'orderId', v_result,\n        'duplicate', true\n      );\n    END IF;\n  END IF;\n\n  -- 2. Read and Lock Customer Profile Row\n  SELECT COALESCE(\\"usedCredit\\", 0), COALESCE(\\"creditLimit\\", 0)\n  INTO v_used_credit, v_credit_limit\n  FROM profiles\n  WHERE id = p_customer_id\n  FOR UPDATE;\n\n  IF NOT FOUND THEN\n    RAISE EXCEPTION 'Customer profile not found for ID %', p_customer_id;\n  END IF;\n\n  -- 3. Validate Credit Limit (if CREDIT customer)\n  IF p_order_type = 'CREDIT' THEN\n    IF (v_used_credit + p_grand_total) > v_credit_limit THEN\n      RAISE EXCEPTION 'Credit limit exceeded. Current used: %, Limit: %, Requested: %', v_used_credit, v_credit_limit, p_grand_total;\n    END IF;\n  END IF;\n\n  -- 4. Update Locked Customer Used Credit Balance\n  v_new_used_credit := v_used_credit + p_grand_total;\n  UPDATE profiles\n  SET \\"usedCredit\\" = v_new_used_credit, \\"updatedAt\\" = v_now_json\n  WHERE id = p_customer_id;\n\n  -- 5. Insert Parent Order (if provided)\n  IF p_parent_order IS NOT NULL THEN\n    INSERT INTO orders (\n      id, \\"customerId\\", \\"customerName\\", \\"customerSnapshot\\", \\"orderType\\", \\"orderSource\\",\n      \\"createdBy\\", \\"createdByRole\\", \\"proxyExecutor\\", \\"printerCategory\\", amounts, delivery,\n      workflow, \\"workflowSnapshot\\", \\"currentWorkflowRole\\", \\"currentWorkflowLabel\\",\n      \\"productionNotes\\", \\"thumbnailUrl\\", \\"productName\\", \\"description\\", items, status, \\"paymentStatus\\",\n      \\"createdAt\\", \\"updatedAt\\", \\"shippingAddress\\", \\"deliveryChoice\\",\n      cgst_percentage, cgst_amount, sgst_percentage, sgst_amount, igst_percentage, igst_amount,\n      gst_type, allocated_logistics_percentage, allocated_logistics_amount, item_amount,\n      taxable_value_snapshot, grand_total_snapshot\n    ) VALUES (\n      p_parent_order->>'id',\n      p_parent_order->>'customerId',\n      p_parent_order->>'customerName',\n      COALESCE(p_parent_order->'customerSnapshot', '{}'::jsonb),\n      p_parent_order->>'orderType',\n      p_parent_order->>'orderSource',\n      p_parent_order->>'createdBy',\n      p_parent_order->>'createdByRole',\n      p_parent_order->'proxyExecutor',\n      p_parent_order->>'printerCategory',\n      p_parent_order->'amounts',\n      p_parent_order->'delivery',\n      p_parent_order->'workflow',\n      p_parent_order->'workflowSnapshot',\n      p_parent_order->>'currentWorkflowRole',\n      p_parent_order->>'currentWorkflowLabel',\n      p_parent_order->>'productionNotes',\n      p_parent_order->>'thumbnailUrl',\n      p_parent_order->>'productName',\n      p_parent_order->>'description',\n      COALESCE(p_parent_order->'items', '[]'::jsonb),\n      p_parent_order->>'status',\n      p_parent_order->>'paymentStatus',\n      COALESCE(p_parent_order->'createdAt', v_now_json),\n      COALESCE(p_parent_order->'updatedAt', v_now_json),\n      p_parent_order->>'shippingAddress',\n      p_parent_order->>'deliveryChoice',\n      (p_parent_order->>'cgst_percentage')::numeric,\n      (p_parent_order->>'cgst_amount')::numeric,\n      (p_parent_order->>'sgst_percentage')::numeric,\n      (p_parent_order->>'sgst_amount')::numeric,\n      (p_parent_order->>'igst_percentage')::numeric,\n      (p_parent_order->>'igst_amount')::numeric,\n      p_parent_order->>'gst_type',\n      (p_parent_order->>'allocated_logistics_percentage')::numeric,\n      (p_parent_order->>'allocated_logistics_amount')::numeric,\n      (p_parent_order->>'item_amount')::numeric,\n      (p_parent_order->>'taxable_value_snapshot')::numeric,\n      (p_parent_order->>'grand_total_snapshot')::numeric\n    );\n  END IF;\n\n  -- 6. Insert Child Orders (Batch)\n  IF p_child_orders IS NOT NULL THEN\n    INSERT INTO orders (\n      id, \\"customerId\\", \\"customerName\\", \\"customerSnapshot\\", \\"orderType\\", \\"orderSource\\",\n      \\"createdBy\\", \\"createdByRole\\", \\"proxyExecutor\\", \\"printerCategory\\", amounts, delivery,\n      workflow, \\"workflowSnapshot\\", \\"currentWorkflowRole\\", \\"currentWorkflowLabel\\",\n      \\"productionNotes\\", \\"thumbnailUrl\\", \\"productName\\", \\"description\\", items, status, \\"paymentStatus\\",\n      \\"createdAt\\", \\"updatedAt\\", \\"shippingAddress\\", \\"deliveryChoice\\",\n      cgst_percentage, cgst_amount, sgst_percentage, sgst_amount, igst_percentage, igst_amount,\n      gst_type, allocated_logistics_percentage, allocated_logistics_amount, item_amount,\n      taxable_value_snapshot, grand_total_snapshot\n    )\n    SELECT\n      child_val->>'id',\n      child_val->>'customerId',\n      child_val->>'customerName',\n      COALESCE(child_val->'customerSnapshot', '{}'::jsonb),\n      child_val->>'orderType',\n      child_val->>'orderSource',\n      child_val->>'createdBy',\n      child_val->>'createdByRole',\n      child_val->'proxyExecutor',\n      child_val->>'printerCategory',\n      child_val->'amounts',\n      child_val->'delivery',\n      child_val->'workflow',\n      child_val->'workflowSnapshot',\n      child_val->>'currentWorkflowRole',\n      child_val->>'currentWorkflowLabel',\n      child_val->>'productionNotes',\n      child_val->>'thumbnailUrl',\n      child_val->>'productName',\n      child_val->>'description',\n      COALESCE(child_val->'items', '[]'::jsonb),\n      child_val->>'status',\n      child_val->>'paymentStatus',\n      COALESCE(child_val->'createdAt', v_now_json),\n      COALESCE(child_val->'updatedAt', v_now_json),\n      child_val->>'shippingAddress',\n      child_val->>'deliveryChoice',\n      (child_val->>'cgst_percentage')::numeric,\n      (child_val->>'cgst_amount')::numeric,\n      (child_val->>'sgst_percentage')::numeric,\n      (child_val->>'sgst_amount')::numeric,\n      (child_val->>'igst_percentage')::numeric,\n      (child_val->>'igst_amount')::numeric,\n      child_val->>'gst_type',\n      (child_val->>'allocated_logistics_percentage')::numeric,\n      (child_val->>'allocated_logistics_amount')::numeric,\n      (child_val->>'item_amount')::numeric,\n      (child_val->>'taxable_value_snapshot')::numeric,\n      (child_val->>'grand_total_snapshot')::numeric\n    FROM unnest(p_child_orders) AS child_val;\n  END IF;\n\n  -- 7. Insert Order Items into order_items table (Batch)\n  IF p_order_items IS NOT NULL THEN\n    INSERT INTO order_items (\n      id, order_id, product_name, product_id, category, project_name, specs, material_metadata,\n      pricing_snapshot, file_url, design_url, design_status, design_upload_stats,\n      \\"assignedPrinterId\\", \\"assignedPrinterName\\", \\"fileUrl\\", \\"productId\\", \\"productName\\",\n      \\"projectName\\", \\"materialMetadata\\", \\"pricingSnapshot\\", \\"designUrl\\", \\"designStatus\\",\n      \\"designUploadStats\\", description, \\"designType\\", \\"itemWorkspace\\", created_at, updated_at\n    )\n    SELECT\n      item_val->>'id',\n      item_val->>'orderId',\n      item_val->>'productName',\n      item_val->>'productId',\n      item_val->>'category',\n      item_val->>'projectName',\n      COALESCE(item_val->'specs', '{}'::jsonb),\n      COALESCE(item_val->'materialMetadata', '{}'::jsonb),\n      COALESCE(item_val->'pricingSnapshot', '{}'::jsonb),\n      item_val->>'fileUrl',\n      item_val->>'designUrl',\n      item_val->>'designStatus',\n      COALESCE(item_val->'designUploadStats', '{}'::jsonb),\n      item_val->>'assignedPrinterId',\n      item_val->>'assignedPrinterName',\n      item_val->>'fileUrl',\n      item_val->>'productId',\n      item_val->>'productName',\n      item_val->>'projectName',\n      COALESCE(item_val->'materialMetadata', '{}'::jsonb),\n      COALESCE(item_val->'pricingSnapshot', '{}'::jsonb),\n      item_val->>'designUrl',\n      item_val->>'designStatus',\n      COALESCE(item_val->'designUploadStats', '{}'::jsonb),\n      item_val->>'description',\n      item_val->>'designType',\n      COALESCE(item_val->'itemWorkspace', '{}'::jsonb),\n      v_now,\n      v_now\n    FROM unnest(p_order_items) AS item_val;\n  END IF;\n\n  -- 8. Insert Ledger Entries into transactions table (Batch)\n  IF p_ledger_entries IS NOT NULL THEN\n    INSERT INTO transactions (\n      id, \\"userId\\", type, \\"ledgerType\\", \\"refId\\", debit, credit, \\"balanceBefore\\", \\"balanceAfter\\",\n      \\"availableCredit\\", remarks, \\"createdBy\\", timestamp, \\"isVerified\\", \\"verifiedAt\\", \\"verifiedBy\\",\n      \\"paymentId\\"\n    )\n    SELECT\n      ledger_val->>'id',\n      ledger_val->>'userId',\n      ledger_val->>'type',\n      ledger_val->>'ledgerType',\n      ledger_val->>'refId',\n      COALESCE((ledger_val->>'debit')::numeric, 0),\n      COALESCE((ledger_val->>'credit')::numeric, 0),\n      COALESCE((ledger_val->>'balanceBefore')::numeric, 0),\n      COALESCE((ledger_val->>'balanceAfter')::numeric, 0),\n      COALESCE((ledger_val->>'availableCredit')::numeric, 0),\n      ledger_val->>'remarks',\n      ledger_val->>'createdBy',\n      COALESCE(ledger_val->>'timestamp', v_now::text)::timestamp with time zone,\n      COALESCE((ledger_val->>'isVerified')::boolean, false),\n      (ledger_val->>'verifiedAt')::timestamp with time zone,\n      ledger_val->>'verifiedBy',\n      ledger_val->>'paymentId'\n    FROM unnest(p_ledger_entries) AS ledger_val;\n  END IF;\n\n  -- 9. Insert Jobs into job_queue table (Batch)\n  IF p_jobs IS NOT NULL THEN\n    INSERT INTO job_queue (\n      id, job_type, order_id, priority, payload, status, created_at, updated_at\n    )\n    SELECT\n      job_val->>'jobId',\n      job_val->>'jobType',\n      job_val->>'orderId',\n      COALESCE((job_val->>'priority')::integer, 0),\n      COALESCE(job_val->'payload', '{}'::jsonb),\n      'PENDING',\n      v_now,\n      v_now\n    FROM unnest(p_jobs) AS job_val;\n  END IF;\n\n  -- 10. Record Idempotency Key (if provided)\n  IF p_idempotency_key IS NOT NULL THEN\n    INSERT INTO idempotency_keys (idempotency_key, order_id, created_at)\n    VALUES (p_idempotency_key, COALESCE(p_parent_order->>'id', (p_child_orders[1])->>'id'), v_now);\n  END IF;\n\n  -- 11. Return Success\n  RETURN jsonb_build_object(\n    'success', true,\n    'orderId', COALESCE(p_parent_order->>'id', (p_child_orders[1])->>'id'),\n    'duplicate', false\n  );\nEXCEPTION WHEN OTHERS THEN\n  RETURN jsonb_build_object(\n    'success', false,\n    'error', SQLERRM\n  );\nEND;\n$$"}	fix_place_order_tx_new_columns
