n  UPDATE profiles\n  SET \n    \\"usedCredit\\" = COALESCE(\\"usedCredit\\", 0) - p_amount,\n    current_recharge = COALESCE(current_recharge, 0) + p_amount\n  WHERE id = p_customer_id;\n\n  -- Process Allocations (Against Reference)\n  IF p_allocations IS NOT NULL AND jsonb_array_length(p_allocations) > 0 THEN\n    FOR v_allocation IN SELECT * FROM jsonb_array_elements(p_allocations)\n    LOOP\n      v_order_id := v_allocation->>'orderId';\n      v_alloc_amount := (v_allocation->>'amount')::NUMERIC;\n      \n      IF v_order_id IS NOT NULL AND v_alloc_amount > 0 THEN\n        -- Update the order's amount_paid\n        UPDATE orders\n        SET amount_paid = COALESCE(amount_paid, 0) + v_alloc_amount,\n            receipt_entry_number = CASE WHEN receipt_entry_number IS NULL THEN p_receipt_entry_number ELSE receipt_entry_number || ',' || p_receipt_entry_number END\n        WHERE id = v_order_id\n        RETURNING grand_total_snapshot, amount_paid INTO v_grand_total, v_new_amount_paid;\n        \n        -- If fully paid, set receipt_created = true\n        IF v_new_amount_paid >= v_grand_total THEN\n          UPDATE orders SET receipt_created = true WHERE id = v_order_id;\n        END IF;\n      END IF;\n    END LOOP;\n  END IF;\n\n  RETURN jsonb_build_object('success', true, 'receiptEntryNumber', p_receipt_entry_number);\nEXCEPTION WHEN OTHERS THEN\n  RETURN jsonb_build_object('success', false, 'error', SQLERRM);\nEND;\n$$"}	add_link_to_transactions
20260715000000	{"-- Suppliers table\nCREATE TABLE IF NOT EXISTS public.suppliers (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name text NOT NULL,\n  gstin text,\n  address text,\n  state text,\n  phone text,\n  email text,\n  tally_ledger_name text,\n  created_at timestamp with time zone DEFAULT now(),\n  created_by text\n)","-- Payment Entries table\nCREATE TABLE IF NOT EXISTS public.payment_entries (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  payment_number text NOT NULL UNIQUE,\n  supplier_id uuid REFERENCES public.suppliers(id) ON DELETE SET NULL,\n  amount numeric NOT NULL,\n  payment_mode text NOT NULL,\n  ref_number text,\n  remarks text,\n  tally_sync_status text DEFAULT 'PENDING',\n  created_at timestamp with time zone DEFAULT now(),\n  created_by text\n)","-- Journal Entries table\nCREATE TABLE IF NOT EXISTS public.journal_entries (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  journal_number text NOT NULL UNIQUE,\n  source_customer_id text NOT NULL, -- references firebase profiles (text id)\n  target_customer_id text NOT NULL, -- references firebase profiles (text id)\n  amount numeric NOT NULL,\n  remarks text,\n  tally_sync_status text DEFAULT 'PENDING',\n  created_at timestamp with time zone DEFAULT now(),\n  created_by text\n)","-- Contra Entries table\nCREATE TABLE IF NOT EXISTS public.contra_entries (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  contra_number text NOT NULL UNIQUE,\n  source_ledger text NOT NULL,\n  target_ledger text NOT NULL,\n  amount numeric NOT NULL,\n  remarks text,\n  tally_sync_status text DEFAULT 'PENDING',\n  created_at timestamp with time zone DEFAULT now(),\n  created_by text\n)","-- Quotations table\nCREATE TABLE IF NOT EXISTS public.quotations (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  quotation_number text NOT NULL UNIQUE,\n  customer_id text NOT NULL, -- references firebase profiles\n  total_amount numeric NOT NULL,\n  items jsonb,\n  tax_details jsonb,\n  tally_sync_status text DEFAULT 'PENDING',\n  created_at timestamp with time zone DEFAULT now(),\n  created_by text\n)","-- RLS policies\nALTER TABLE public.suppliers ENABLE ROW LEVEL SECURITY","ALTER TABLE public.payment_entries ENABLE ROW LEVEL SECURITY","ALTER TABLE public.journal_entries ENABLE ROW LEVEL SECURITY","ALTER TABLE public.contra_entries ENABLE ROW LEVEL SECURITY","ALTER TABLE public.quotations ENABLE ROW LEVEL SECURITY","CREATE POLICY \\"Allow read access to authenticated users\\" ON public.suppliers FOR SELECT USING (auth.role() = 'authenticated')","CREATE POLICY \\"Allow insert access to authenticated users\\" ON public.suppliers FOR INSERT WITH CHECK (auth.role() = 'authenticated')","CREATE POLICY \\"Allow update access to authenticated users\\" ON public.suppliers FOR UPDATE USING (auth.role() = 'authenticated')","CREATE POLICY \\"Allow read access to authenticated users\\" ON public.payment_entries FOR SELECT USING (auth.role() = 'authenticated')","CREATE POLICY \\"Allow insert access to authenticated users\\" ON public.payment_entries FOR INSERT WITH CHECK (auth.role() = 'authenticated')","CREATE POLICY \\"Allow update access to authenticated users\\" ON public.payment_entries FOR UPDATE USING (auth.role() = 'authenticated')","CREATE POLICY \\"Allow read access to authenticated users\\" ON public.journal_entries FOR SELECT USING (auth.role() = 'authenticated')","CREATE POLICY \\"Allow insert access to authenticated users\\" ON public.journal_entries FOR INSERT WITH CHECK (auth.role() = 'authenticated')","CREATE POLICY \\"Allow update access to authenticated users\\" ON public.journal_entries FOR UPDATE USING (auth.role() = 'authenticated')","CREATE POLICY \\"Allow read access to authenticated users\\" ON public.contra_entries FOR SELECT USING (auth.role() = 'authenticated')","CREATE POLICY \\"Allow insert access to authenticated users\\" ON public.contra_entries FOR INSERT WITH CHECK (auth.role() = 'authenticated')","CREATE POLICY \\"Allow update access to authenticated users\\" ON public.contra_entries FOR UPDATE USING (auth.role() = 'authenticated')","CREATE POLICY \\"Allow read access to authenticated users\\" ON public.quotations FOR SELECT USING (auth.role() = 'authenticated')","CREATE POLICY \\"Allow insert access to authenticated users\\" ON public.quotations FOR INSERT WITH CHECK (auth.role() = 'authenticated')","CREATE POLICY \\"Allow update access to authenticated users\\" ON public.quotations FOR UPDATE USING (auth.role() = 'authenticated')","-- Grant permissions to service role\nGRANT ALL ON TABLE public.suppliers TO service_role","GRANT ALL ON TABLE public.payment_entries TO service_role","GRANT ALL ON TABLE public.journal_entries TO service_role","GRANT ALL ON TABLE public.contra_entries TO service_role","GRANT ALL ON TABLE public.quotations TO service_role"}	accounting_vouchers_tables
